def _normalize_site_catalog_phrase(value: Any) -> str:
    return re.sub(r"[^a-zа-яіїєґ0-9]+", " ", str(value or "").lower().replace("ё", "е"), flags=re.IGNORECASE).strip()


# Exact phrase index is constructed once at import; runtime route lookup is O(1).
APRIL_UI_HELP_QUERY_INDEX: dict[str, list[dict[str, Any]]] = {}
for _catalog_case in APRIL_UI_HELP_QUERY_CATALOG:
    _normalized_case_query = _normalize_site_catalog_phrase(_catalog_case.get("query"))
    if _normalized_case_query:
        APRIL_UI_HELP_QUERY_INDEX.setdefault(_normalized_case_query, []).append(_catalog_case)
for _alias_row in APRIL_UI_HELP_ALIAS_ROWS:
    _case_id, _query, _area_id, _family, _path, _outputs = _alias_row
    _normalized_case_query = _normalize_site_catalog_phrase(_query)
    if _normalized_case_query:
        APRIL_UI_HELP_QUERY_INDEX.setdefault(_normalized_case_query, []).append({
            "case_id": _case_id, "query": _query, "area_id": _area_id,
            "intent_family": _family, "expected_path": _path, "expected_outputs": _outputs,
            "evidence": "APRIL_SITE_MAP + source snapshot",
        })
APRIL_UI_HELP_QUERY_CASE_COUNT = len({case[0] for case in APRIL_UI_HELP_ALIAS_ROWS}) + len(APRIL_UI_HELP_QUERY_CATALOG)


_SITE_NAVIGATION_ACTION_RE = re.compile(
    r"(?:куда\s+(?:мне\s+)?(?:зайти|нажать|перейти|открыть)|как\s+(?:зайти|попасть|перейти|открыть|найти|посмотреть|просмотреть|скачать|сохранить|скопировать|поделиться)|"
    r"как.{0,70}?(?:скача\w*|сохран\w*|скопир\w*|поделит\w*|download|save|copy|share)|"
    r"где\s+(?:(?:у\s+(?:меня|тебя|вас|april|април)\s+)?(?:находится|расположен|найти|открыть|посмотреть|вход|кнопк|ссылк)|.{0,55}(?:вход|кнопк|ссылк))|покажи\s+(?:мне\s+)?(?:куда|путь|раздел|ссылк)|"
    r"проведи\s+меня|как\s+пользоваться|по\s+сайту|по\s+интерфейсу|навигац|"
    r"where\s+(?:do\s+i|can\s+i)|how\s+do\s+i\s+(?:open|find|navigate|download|save|copy|share)|how\s+to\s+(?:download|save|copy|share)|where\s+is|show\s+me\s+where)",
    re.IGNORECASE,
)

# Explicit interface targets are separate from generic media nouns. Merely saying
# "show it in a picture" or "help me connect this" is not a request to navigate April.
_SITE_UI_TARGET_RE = re.compile(
    r"(?:кабинет|профил\w*|аккаунт|раздел|кнопк\w*|меню|сайт|интерфейс|страниц\w*|"
    r"истор\w*\s+диалог\w*|сообществ\w*|тариф\w*|подписк\w*|памят\w*|удален\w*|"
    r"поддержк\w*|community|profile|account|settings|history|support|help center|features|capabilities|"
    r"april\s+(?:web|interface|site|screen|account|profile)|април\w*.{0,25}(?:сайт|интерфейс|страниц|профил|настройк)|"
    r"эйприл\w*.{0,25}(?:сайт|интерфейс|страниц|профил|настройк)|скриншот\w*|снимок\s+экрана|"
    r"screen\s+(?:of\s+)?april|screenshot|website|web\s+interface|ui\b)",
    re.IGNORECASE,
)
_SITE_GENERIC_MEDIA_RE = re.compile(
    r"(?:картинк\w*|изображени\w*|фото\w*|picture\w*|image\w*|photo\w*)",
    re.IGNORECASE,
)
_SITE_MEDIA_CONTROL_ACTION_RE = re.compile(
    r"(?:скача\w*|сохран\w*|скопир\w*|поделит\w*|download|save|copy|share|"
    r"куда\s+нажать|какую\s+кнопку|кнопк\w*|меню\s+действий|стрелк\w*|указател\w*|mark|point\s+out)",
    re.IGNORECASE,
)

def _has_site_ui_target(query: str) -> bool:
    """Recognize an actual April/UI referent, not a generic picture or diagram."""
    low = str(query or "").lower().replace("ё", "е")
    if _SITE_UI_TARGET_RE.search(low):
        return True
    # Image-control questions are UI help only when the requested action concerns
    # saving/sharing/copying/downloading or a visible control, not any picture request.
    return bool(_SITE_GENERIC_MEDIA_RE.search(low) and _SITE_MEDIA_CONTROL_ACTION_RE.search(low))

_SITE_HELP_NEGATION_RE = re.compile(
    r"(?:\bне\s+(?:надо|нужно|нужен|нужна|нужны|хочу|спрашиваю|говорю|про|об|о)\b|"
    r"\bне\s+интересу(?:ет|ют)\b|"
    r"\b(?:no|not)\s+(?:need|want|asking\s+about)\b|"
    r"\b(?:don't|do\s+not)\s+(?:need|want)\b)",
    re.IGNORECASE,
)
_SITE_HELP_CONTRAST_SPLIT_RE = re.compile(
    r"(?<=[.!?;])\s+|,\s*|\s+(?:а|но|однако|зато|вместо\s+этого|but|however|instead)\s+",
    re.IGNORECASE,
)


def _effective_site_help_query(query: Any) -> tuple[str, bool]:
    """Remove clauses that explicitly reject April-site help before routing.

    A mention such as "не надо сайт по сообществу, а нарисуй синхрофазатрон"
    is a correction, not a request to open Community. Keep positive clauses so a
    second, explicit UI-navigation request in the same message still works.
    """
    raw = str(query or "").strip().replace("ё", "е")
    if not raw:
        return "", False
    kept: list[str] = []
    removed_negative_ui_clause = False
    for clause in _SITE_HELP_CONTRAST_SPLIT_RE.split(raw):
        part = clause.strip()
        if not part:
            continue
        targets = list(_SITE_UI_TARGET_RE.finditer(part))
        negations = list(_SITE_HELP_NEGATION_RE.finditer(part))
        negative_ui_clause = False
        for negation in negations:
            for target in targets:
                # The negation must be close to, and grammatically adjacent to,
                # the UI target. This deliberately does not match "не могу найти".
                distance = target.start() - negation.end()
                reverse_distance = negation.start() - target.end()
                if (0 <= distance <= 100) or (0 <= reverse_distance <= 45):
                    negative_ui_clause = True
                    break
            if negative_ui_clause:
                break
        if negative_ui_clause:
            removed_negative_ui_clause = True
            continue
        kept.append(part)
    return " ".join(kept).strip(), removed_negative_ui_clause

def _site_navigation_picture_request(query: str, referenced_area_ids: Any = None) -> bool:
    """Route visual questions about April UI to its real SVG navigation map."""
    effective_query, removed_negative_clause = _effective_site_help_query(query)
    low = effective_query.strip().lower().replace("ё", "е")
    if not low or (removed_negative_clause and not is_site_help_query(low)):
        return False
    referenced_ids = {str(value).strip().lower() for value in (referenced_area_ids or []) if str(value).strip()} if isinstance(referenced_area_ids, (list, tuple, set)) else set()
    explicit_ui_target = _has_site_ui_target(low)
    # A stale site-navigation anchor must not override a complete new task. Keep
    # inherited UI referents only for short/elliptical follow-ups or text that names
    # a real interface target or a UI-specific image action.
    substantive_words = _site_words(low)
    if len(substantive_words) >= 7 and not explicit_ui_target:
        referenced_ids = set()
    referenced_ui_target = bool(referenced_ids.intersection({"space", "history", "settings", "support", "guide", "help-center", "how-to-use", "plans", "deletion", "privacy", "terms", "memory", "chat", "image-controls"}))
    ui_target = explicit_ui_target or referenced_ui_target
    if not ui_target or _SITE_NO_DIAGRAM_RE.search(low):
        return False
    if re.search(
        r"(?:только\s+(?:изображен\w*|картинк\w*|фото|портрет)|only\s+(?:an?\s+)?image)",
        low, re.IGNORECASE,
    ):
        return False
    # A real portrait/person/landscape request still goes to image generation.
    explicit_art = bool(re.search(
        r"(?:сгенерируй|создай|нарисуй|изобрази)\s+(?:мне\s+)?(?:фото|портрет|иллюстрац\w*|"
        r"картинк\w*\s+(?:человека|персонажа|пейзажа)|изображение\s+(?:человека|персонажа|пейзажа)|арт\b)|"
        r"(?:generate|create|draw)\s+(?:a\s+)?(?:portrait|person|character|landscape|artwork)",
        low, re.IGNORECASE,
    ))
    if explicit_art:
        return False
    asks_visual_path = bool(re.search(
        r"(?:на\s+(?:картинк\w*|изображени\w*|схем\w*)|визуальн\w*\s+путь|стрелк\w*|указател\w*|"
        r"(?:полна\w*|весь|все|всю|карт\w*|структур\w*|схем\w*|обзор\w*).{0,70}(?:интерфейс\w*|сайт\w*|экран\w*|страниц\w*|раздел\w*|навигац\w*)|"
        r"покажи.{0,100}(?:путь|куда|интерфейс|меню|вход|картинк\w*|изображени\w*|схем\w*|стрелк\w*|указател\w*)|"
        r"(?:где|куда|как\s+(?:зайти|попасть|открыть|перейти)).{0,100}(?:картинк\w*|изображени\w*|схем\w*)|"
        r"show.{0,100}(?:path|where|interface|menu|picture|image|diagram)|"
        r"(?:where\s+(?:is|do\s+i|can\s+i)|how\s+do\s+i\s+(?:open|find|navigate)).{0,100}(?:picture|image|diagram))",
        low, re.IGNORECASE,
    ))
    asks_to_annotate_ui_path = bool(
        re.search(
            r"(?:на\s+(?:этой\s+|присланной\s+|предыдущей\s+)?(?:картинк\w*|изображени\w*|скриншот\w*)|"
            r"(?:this|the|attached|previous)\s+(?:picture|image|screenshot))",
            low, re.IGNORECASE,
        )
        and re.search(
            r"(?:стрелк\w*|указател\w*|куда\s+нажать|показ\w*\s+путь|истори\w*\s+диалог\w*|"
            r"сообществ\w*|community|saved\s+dialogues?|history|кнопк\w*|скача\w*|сохран\w*|"
            r"скопир\w*|поделит\w*|download|save|copy|share|в\s+чате|на\s+телефон\w*)",
            low, re.IGNORECASE,
        )
    )
    # For an interface tutorial, a user may name the existing image before saying
    # "show/point out how to save it". Route this to April's SVG control map, not
    # to a new raster image, even when the action words appear in reverse order.
    asks_image_control_path = bool(
        re.search(r"(?:картинк\w*|изображени\w*|фото\b|picture\w*|image\w*|photo\w*)", low, re.I)
        and re.search(r"(?:скача\w*|сохран\w*|скопир\w*|поделит\w*|download|save|copy|share)", low, re.I)
        and re.search(r"(?:покаж\w*|укаж\w*|отмет\w*|стрелк\w*|куда\s+нажать|show|point\s+out|mark)", low, re.I)
    )
    return asks_visual_path or asks_to_annotate_ui_path or asks_image_control_path or bool(_SITE_EXPLICIT_RASTER_REQUEST_RE.search(low))


_SITE_ROUTE_WORDS = (
    "сообществ", "community", "личный кабинет", "кабинет april", "april id", "premium id",
    "история диалогов", "saved dialogues", "help center", "how to use april", "plans & payments",
    "account deletion", "удаление аккаунта", "privacy policy", "terms of service", "/settings",
    "/history", "/space", "/aprill", "/account-deletion", "/insights?room=support",
    "профиль пользователя", "тарифы и платежи", "контакт с поддержкой",
)


def _is_attachment_instruction_query(query: Any) -> bool:
    """Distinguish instructions for uploading media into chat from image editing/generation."""
    low = str(query or "").strip().lower().replace("ё", "е")
    if not low:
        return False
    media = bool(re.search(r"(?:картинк\w*|изображени\w*|фот\w*|снимк\w*|файл\w*|picture\w*|image\w*|photo\w*|file\w*)", low))
    upload_action = bool(re.search(r"(?:прикреп\w*|добав\w*|загруз\w*|выбрат\w*|отправ\w*|attach\w*|upload\w*|add\w*|select\w*)", low))
    how_to = bool(re.search(r"(?:расскаж\w*.{0,35}как|объясн\w*.{0,35}как|подскажи\w*.{0,35}как|покажи\w*.{0,35}как|помоги\w*.{0,35}(?:прикреп|добав|загруз)|^как\b|куда\s+нажать|по\s+шагам|пошаг|how\s+(?:do\s+i|to)|show\s+me\s+how)", low, re.I | re.S))
    chat_target = bool(re.search(r"(?:в\s+(?:тво[её]м|этот|основн\w*|главн\w*)\s+(?:пространств\w*|чат\w*|диалог\w*)|в\s+чат\w*|в\s+переписк\w*|чтобы\s+(?:ты|април\w*)\s+(?:увид\w*|получил\w*|прочитал\w*)|so\s+(?:you|april)\s+can\s+(?:see|view|read)|in\s+(?:the\s+)?chat)", low, re.I))
    # Object placement/annotation refers to editing a photo, not uploading it.
    edit_surface = bool(re.search(r"(?:на\s+(?:эту\s+|этой\s+|этот\s+|мою\s+)?(?:фот\w*|картинк\w*|изображени\w*)|добав\w*.{0,55}\b(?:евро|гривн|надпис|объект|стрелк)\b)", low, re.I | re.S))
    return media and upload_action and chat_target and (how_to or bool(re.search(r"чтобы\s+(?:ты|април\w*)\s+(?:увид\w*|получил\w*)", low))) and not edit_surface


_SITE_INTERFACE_OVERVIEW_RE = re.compile(
    r"(?:\b(?:full|complete|entire|whole|overview|map|structure)\b.{0,80}\b(?:april\s+)?(?:interface|site|website|web|screens?|pages?|navigation|ui)\b|"
    r"(?:полна\w*|весь|все|всю|кажд\w*|общ\w*|карт\w*|структур\w*|схем\w*|обзор\w*|перечисл\w*)\s*.{0,80}(?:интерфейс\w*|сайт\w*|веб\w*|экран\w*|страниц\w*|раздел\w*|навигац\w*|функци\w*|меню\b)|"
    r"(?:функци\w*|возможност\w*|кнопк\w*|элемент\w*)\s*.{0,80}(?:веб\w*|сайт\w*|интерфейс\w*|web\b|website|site\b|april\b)|"
    r"(?:интерфейс\w*|сайт\w*|веб\w*|website|web\b)\s*.{0,60}(?:целиком|полностью|карта|структур\w*|обзор\w*|все\s+раздел\w*|все\s+экран\w*|функци\w*)|"
    r"(?:site\s+map|карт\w*\s+сайт\w*|полна\w*\s+карт\w*\s+интерфейс\w*|структура\s+интерфейса|схем\w*\s+интерфейса))",
    re.IGNORECASE,
)


def _site_search_availability_target(value: Any) -> str:
    """Return the real search surface a user is asking about, not a full-site tour."""
    low = str(value or "").lower().replace("ё", "е")
    history_search_ui = bool(re.search(
        r"(?:где\s+(?:находится\s+)?поиск|есть\s+ли\s+поиск|поле\s+поиска|как\s+(?:найти|открыть|пользоваться)\s+(?:строк\w*\s+)?поиск|search\s+(?:field|box))",
        low, re.I,
    )) and bool(re.search(r"(?:истори\w*|диалог\w*|history|conversation)", low, re.I))
    if history_search_ui:
        return "history"
    global_search_ui = bool(re.search(
        r"(?:где\s+(?:находится\s+)?поиск|есть\s+ли\s+поиск|поле\s+поиска|search\s+(?:field|box))",
        low, re.I,
    )) and bool(re.search(r"(?:по\s+всему\s+сайт\w*|поиск\w*.{0,35}(?:по\s+)?(?:вс\w*\s+)?сайт\w*|глобальн\w*\s+поиск|whole\s+site|site[- ]wide)", low, re.I | re.S))
    return "global" if global_search_ui else ""


def _site_full_interface_overview_requested(value: Any) -> bool:
    """Distinguish a whole-site inventory from a complete row/card of controls."""
    low = str(value or "").lower().replace("ё", "е")
    if _site_search_availability_target(low):
        return False
    # "All three buttons under the answer" is a complete local control row,
    # not a request to dump the entire site's navigation/function inventory.
    focused_control_group = bool(re.search(
        r"(?:кнопк\w*|элемент\w*|control\w*).{0,65}(?:под\s+(?:ответ\w*|сообщен\w*)|рядом\s+с\s+(?:ответ\w*|сообщен\w*)|under\s+(?:the\s+)?(?:answer|reply|message)|beneath\s+(?:the\s+)?(?:answer|reply|message))|"
        r"(?:под\s+(?:ответ\w*|сообщен\w*)|under\s+(?:the\s+)?(?:answer|reply|message)).{0,65}(?:кнопк\w*|элемент\w*|control\w*)",
        low, re.I | re.S,
    ))
    if focused_control_group:
        return False
    return bool(_SITE_INTERFACE_OVERVIEW_RE.search(low))


def is_site_help_query(query: str) -> bool:
    """Detect positive April self-help/navigation requests, excluding rejected routes."""
    effective_query, _removed_negative_clause = _effective_site_help_query(query)
    low = effective_query.strip().lower().replace("ё", "е")
    if not low:
        return False
    if _is_external_community_topic(low):
        return False
    if _is_attachment_instruction_query(low):
        return True
    # Explicit questions about the presence/location of search fields are UI help,
    # not requests to search private dialogue content on the user's behalf.
    history_search_ui_question = bool(re.search(
        r"(?:где\s+(?:находится\s+)?поиск|есть\s+ли\s+поиск|поле\s+поиска|как\s+(?:найти|открыть|пользоваться)\s+(?:строк\w*\s+)?поиск|search\s+(?:field|box))",
        low, re.I,
    )) and bool(re.search(r"(?:истори\w*|диалог\w*|history|conversation)", low, re.I))
    site_wide_search_ui_question = bool(re.search(
        r"(?:где\s+(?:находится\s+)?поиск|есть\s+ли\s+поиск|поле\s+поиска|search\s+(?:field|box))",
        low, re.I,
    )) and bool(re.search(r"(?:вс\w*\s+сайт\w*|глобальн\w*\s+поиск|по\s+всему\s+сайт\w*|whole\s+site|site[- ]wide)", low, re.I))
    if history_search_ui_question or site_wide_search_ui_question:
        return True
    # Direct route/section names are enough: a user can simply type "Сообщество".
    if any(term in low for term in _SITE_ROUTE_WORDS):
        return True
    if _normalize_site_catalog_phrase(low) in APRIL_UI_HELP_QUERY_INDEX:
        return True
    if _SITE_INTERFACE_OVERVIEW_RE.search(low):
        return True
    # Broad questions about April's own capabilities should be grounded in the
    # real site map as well, so users receive both a description and entry points.
    april_self_help = bool(re.search(
        r"(?:\b(?:april|април)\b.{0,100}\b(?:функци\w*|возможност\w*|устроен\w*|работа\w*|создан\w*|умеешь|умеет|можешь|может)\b|"
        r"\b(?:функци\w*|возможност\w*)\b.{0,100}\b(?:april|април)\b|"
        r"(?:what can april do|how does april work|how is april built))",
        low,
        re.IGNORECASE,
    ))
    if april_self_help or _SITE_GUIDE_TOPIC_RE.search(low):
        return True
    semantic_scores = _semantic_site_area_scores(low)
    semantic_ui_target = any(score >= 2.8 for score, area_id in semantic_scores if area_id != "admin-support")
    ui_target = _has_site_ui_target(low)
    if semantic_ui_target and ui_target and (_SITE_NAVIGATION_ACTION_RE.search(low) or re.search(r"(?:помог\w*|запутал\w*|не\s+нахожу|не\s+могу\s+найти|как\s+работает|куда\s+пройти|что\s+нажать|where|how\s+do\s+i)", low, re.IGNORECASE)):
        return True
    return bool(_SITE_NAVIGATION_ACTION_RE.search(low) and ui_target)


_SITE_NO_DIAGRAM_RE = re.compile(
    r"(?:только\s+текст|без\s+(?:схем|диаграмм|визуализац)|не\s+(?:нужна|нужно|надо)\s+(?:схема|диаграмма)|"
    r"не\s+(?:схему|диаграмму)|не\s+показывай\s+(?:схему|диаграмму)|text\s+only|no\s+diagram|not\s+(?:a\s+)?diagram)",
    re.IGNORECASE,
)
_SITE_EXPLICIT_DIAGRAM_RE = re.compile(r"(?:диаграмм\w*|схем\w*|diagram|flowchart)", re.IGNORECASE)
_SITE_EXPLICIT_RASTER_REQUEST_RE = re.compile(
    r"(?:нарису\w*|созда\w*|сгенериру\w*|изобрази)\s+(?:мне\s+)?(?:реальн\w*\s+|настоящ\w*\s+|текущ\w*\s+)?(?:скриншот\w*|снимок\s+экрана|экран\w*\s+(?:april|април)|интерфейс\w*)|"
    r"(?:покажи\s+(?:это|путь|интерфейс|меню|куда).{0,70}на\s+(?:картинк\w*|изображени\w*|скриншот\w*))|"
    r"(?:покажи\s+(?:полный\s+)?(?:реальн\w*\s+)?(?:скриншот|снимок).{0,70}(?:реальн\w*|настоящ\w*|интерфейс|экран))|"
    r"(?:покажи|предоставь|пришли|дай).{0,50}(?:реальн\w*|настоящ\w*).{0,50}(?:скриншот\w*|снимок\s+экрана|экран)|"
    r"(?:(?:реальн\w*|настоящ\w*).{0,50}(?:скриншот\w*|снимок\s+экрана))|"
    r"(?:real|actual)\s+(?:current\s+)?(?:april\s+)?(?:interface|screen|screenshot)|"
    r"(?:show\s+(?:me\s+)?(?:a\s+)?(?:real|actual|current)\s+(?:screenshot|screen)|show\s+(?:me\s+)?(?:this|the\s+path|the\s+interface).{0,60}(?:in\s+an?\s+image|as\s+an?\s+image|screenshot))|"
    r"(?:draw|create|generate|make)\s+(?:me\s+)?(?:a\s+)?(?:real\s+|actual\s+|current\s+)?(?:screenshot|screen|interface)\b",
    re.IGNORECASE,
)
_SITE_OTHER_RENDERERS = {"image", "gallery", "code", "table", "graph", "formula", "link", "file", "3d_graph"}


def _site_should_render_diagram(query: str, requested_outputs: Any = None) -> bool:
    """Prefer a diagram by default, but respect an explicit alternative renderer or opt-out."""
    low = str(query or "").lower().replace("ё", "е")
    if _SITE_NO_DIAGRAM_RE.search(low):
        return False
    # A visual explanation of an interface path is a vector route map, not an image-generation task.
    if _site_navigation_picture_request(query):
        return True
    if re.search(r"(?:только\s+(?:ссылк\w*|код|таблиц\w*|изображен\w*|картинк\w*|график\w*|формул\w*|файл\w*)|only\s+(?:a\s+)?(?:link|code|table|image|graph|formula|file))", low) and not _SITE_EXPLICIT_DIAGRAM_RE.search(low):
        return False
    if _SITE_EXPLICIT_DIAGRAM_RE.search(low):
        return True
    outputs = {
        str(value or "").strip().lower().replace("-", "_")
        for value in (requested_outputs or [])
        if str(value or "").strip()
    } if isinstance(requested_outputs, (list, tuple, set)) else set()
    aliases = {"plot": "graph", "chart": "graph", "generated_image": "image", "image_gallery": "gallery", "latex": "formula", "math": "formula", "svg": "diagram"}
    outputs = {aliases.get(value, value) for value in outputs}
    return not bool(outputs.intersection(_SITE_OTHER_RENDERERS))


def _requested_outputs_from_machine_request(machine_request: Any) -> List[str]:
    """Read output preferences from the actual request/interpretation envelope."""
    root = machine_request if isinstance(machine_request, dict) else getattr(machine_request, "intent", {})
    if not isinstance(root, dict):
        return []
    sources = [root]
    nested = root.get("intent")
    if isinstance(nested, dict):
        sources.append(nested)
    interpretation = root.get("interpretation")
    if isinstance(interpretation, dict):
        sources.append(interpretation)
        nested_intent = interpretation.get("intent")
        if isinstance(nested_intent, dict):
            sources.append(nested_intent)
    for source in sources:
        values = source.get("requested_outputs")
        if isinstance(values, (list, tuple, set)) and values:
            return [str(value) for value in values]
    return []


_ELLIPTICAL_SITE_FOLLOWUP_RE = re.compile(
    r"(?:где\s+(?:это|там|он|она|они|мне|находится)|куда\s+(?:мне\s+)?(?:зайти|нажать|перейти|идти)|"
    r"покажи\s+(?:мне\s+)?(?:это|где|куда|путь)?|как\s+туда|какую\s+кнопку|"
    r"where\s+is\s+it|where\s+do\s+i\s+go|show\s+me\s+where|how\s+do\s+i\s+get\s+there)",
    re.IGNORECASE,
)


def _recent_context_texts(context: Any) -> List[str]:
    """Extract a small, current-turn continuation window, never a full history dump."""
    if not isinstance(context, dict):
        return []
    out: List[str] = []
    for key in ("active_topic", "topic", "anchor", "selected_section", "active_work_branch"):
        value = context.get(key)
        if isinstance(value, str) and value.strip():
            out.append(value.strip()[:900])
        elif isinstance(value, dict):
            for child_key in ("topic", "user", "april", "heading", "summary", "goal", "last_user_text", "last_assistant_answer"):
                child = value.get(child_key)
                if isinstance(child, str) and child.strip():
                    out.append(child.strip()[:900])
    for pair in (context.get("selected_pairs") or [])[:2] if isinstance(context.get("selected_pairs"), list) else []:
        if not isinstance(pair, dict):
            continue
        for key in (
            "topic", "user", "april", "source_user_text", "source_april_text",
            "assistant_last_message", "assistant_answer", "last_assistant_answer",
        ):
            child = pair.get(key)
            if isinstance(child, str) and child.strip():
                out.append(child.strip()[:1800])
        # Only safe, compact descriptors are inspected. Binary assets are not
        # restored or converted into screenshots by the IT room.
        for key in ("assistant_structured_output", "assistant_artifact_index", "artifact_index"):
            child = pair.get(key)
            if isinstance(child, (dict, list)) and child:
                out.append(str(child)[:1800])
    # Avoid scanning topic indexes or older general history: only the active window
    # and the first two selected pairs may re-anchor an elliptical navigation follow-up.
    return out[:18]



def _interpretation_semantic_features(interpretation: Any) -> Dict[str, Any]:
    """Read semantic features from the current Interpretation envelope."""
    if not isinstance(interpretation, dict):
        return {}
    request_structure = interpretation.get("request_structure") if isinstance(interpretation.get("request_structure"), dict) else {}
    semantics = request_structure.get("semantic_interpretation") if isinstance(request_structure.get("semantic_interpretation"), dict) else {}
    if not semantics and isinstance(interpretation.get("semantic_interpretation"), dict):
        semantics = interpretation.get("semantic_interpretation")
    if not semantics and isinstance(interpretation.get("intent_features"), dict):
        semantics = {"intent_features": interpretation.get("intent_features")}
    return dict(semantics) if isinstance(semantics, dict) else {}


def _active_site_ui_followup(interpretation: Any, query: str, recent_context: Any) -> Dict[str, Any]:
    """Resolve an elliptical control question against the active April-UI exchange.

    A state-manager relation label is advisory, not a hard gate: the semantic
    pre-interpreter can label "what does the green button do?" as NEW even when
    the selected active pair is plainly an April interface explanation.
    """
    if not isinstance(recent_context, dict) or not isinstance(interpretation, dict):
        return {}
    semantics = _interpretation_semantic_features(interpretation)
    features = semantics.get("features") if isinstance(semantics.get("features"), dict) else {}
    if not features and isinstance(semantics.get("intent_features"), dict):
        features = semantics.get("intent_features")
    dialogue = interpretation.get("dialogue") if isinstance(interpretation.get("dialogue"), dict) else {}
    interaction = dialogue.get("interaction_profile") if isinstance(dialogue.get("interaction_profile"), dict) else {}
    if semantics.get("explicit_topic_switch") or features.get("explicit_topic_switch") or semantics.get("history_request"):
        return {}

    control_kind = _site_control_reference_kind(query)
    context_question = bool(
        features.get("context_dependent_question")
        or features.get("previous_assistant_output_reference")
        or features.get("strong_anaphoric_reference")
        or interaction.get("previous_answer_reference")
        or control_kind
    )
    if not context_question:
        return {}

    selected_pairs = recent_context.get("selected_pairs") if isinstance(recent_context.get("selected_pairs"), list) else []
    candidates = []
    for pair in selected_pairs[:5]:
        if not isinstance(pair, dict):
            continue
        user_text = _text(pair.get("user") or pair.get("source_user_text"))
        assistant_text = _text(
            pair.get("assistant_last_message") or pair.get("source_april_text") or
            pair.get("assistant_answer") or pair.get("april")
        )
        if not user_text:
            continue
        pair_text = " ".join((user_text, assistant_text))
        # Require a previous positively identified April UI-help turn. Do not use
        # unrelated history just because it contains the word "button".
        pair_control = _site_control_reference_kind(pair_text)
        prior_is_site_help = is_site_help_query(user_text) or bool(pair_control)
        if not prior_is_site_help:
            continue
        area_ids = _referenced_site_area_ids({"selected_pairs": [pair]})
        if pair_control == "assistant_response_share":
            area_ids = list(dict.fromkeys(["response-feedback", "chat", "space", *area_ids]))
        elif pair_control in {"response_feedback_thanks", "response_feedback_report"}:
            area_ids = list(dict.fromkeys(["response-feedback", "chat", *area_ids]))
        if not area_ids:
            continue
        candidates.append((user_text, assistant_text, pair_text, area_ids))
    if not candidates:
        return {}

    # Current control wording determines the exact action. For a follow-up that
    # only says "what does it do?", fall back to a unique control described in
    # the active pair's answer, not to every item on that page.
    resolved_ids: List[str] = []
    resolved_targets: List[str] = []
    if control_kind == "assistant_response_share":
        resolved_ids = ["assistant_response_share"]
        resolved_targets = ["response.share_to_community"]
    elif control_kind in {"response_feedback_thanks", "response_feedback_report"}:
        resolved_ids = ["response_feedback"]
        resolved_targets = ["response.feedback"]
    else:
        active_text = " ".join(item[2] for item in candidates[:2])
        prior_control = _site_control_reference_kind(active_text)
        if prior_control == "assistant_response_share":
            resolved_ids = ["assistant_response_share"]
            resolved_targets = ["response.share_to_community"]
        elif prior_control in {"response_feedback_thanks", "response_feedback_report"}:
            resolved_ids = ["response_feedback"]
            resolved_targets = ["response.feedback"]

    if not resolved_ids:
        # Generic contextual questions are accepted only when the selected active
        # answer contains a single concrete site-control target and the current
        # turn is an explicit anaphoric continuation.
        semantic = {
            "domain": "april_ui", "action": "EXPLAIN_UI_ROUTE",
            "user_goal": " ".join((query, candidates[0][2])),
        }
        matched = _site_semantic_function_targets(query, semantic, candidates[0][3])
        resolved_ids = list(matched.get("function_ids") or [])
        resolved_targets = list(matched.get("semantic_targets") or [])
    if not resolved_ids:
        return {}

    prior_user, prior_answer, _pair_text, prior_areas = candidates[0]
    area_ids = ["response-feedback", "chat", "space"] if "assistant_response_share" in resolved_ids else ["response-feedback", "chat"]
    if not area_ids:
        area_ids = prior_areas
    relation = _text(recent_context.get("relation") or dialogue.get("relation")).upper()
    return {
        "relation": relation,
        "area_ids": area_ids[:4],
        "function_ids": resolved_ids[:4],
        "semantic_targets": resolved_targets[:4],
        "prior_user_request": prior_user[:360],
        "prior_answer_excerpt": prior_answer[:900],
        "source": "active_site_help_pair_semantic_control_match",
    }

def _referenced_site_area_ids(context: Any) -> List[str]:
    rows = _recent_context_texts(context)
    source = " ".join(rows).lower().replace("ё", "е")
    if not source:
        return []
    ids: List[str] = []
    # Specific current-route clues take precedence over generic words such as "chat".
    for area_id in ("response-feedback", "space", "settings", "history", "support", "guide", "deletion", "privacy", "terms", "plans", "how-to-use", "help-center", "memory", "direct", "chat", "tools"):
        hints = _SITE_AREA_HINTS.get(area_id, ())
        if any(hint in source for hint in hints) or any(
            marker in source for marker in {
                "response-feedback": ("response-feedback", "жалоб", "пожалова", "поблагодар", "отблагодар", "спасибо", "зелёная стрелка", "зеленая стрелка", "опубликовать в сообществе", "reportairesponse"),
                "space": ("/space", "community", "сообществ", "private chat"),
                "settings": ("/settings", "личный кабинет", "профиль", "current plan"),
                "history": ("/history", "saved dialogues", "история диалогов", "continue this dialogue"),
                "support": ("/insights?room=support", "contact support", "поддержк"),
                "guide": ("/aprill", "help & information"),
                "deletion": ("/account-deletion", "account & data deletion"),
                "privacy": ("/privacy-policy", "privacy policy"),
                "terms": ("/terms-of-service", "terms of service"),
                "plans": ("plans & payments", "time remaining", "premium"),
                "how-to-use": ("how to use april",),
                "help-center": ("help center",),
                "memory": ("/memory", "memory status"),
                "direct": ("/space/direct/", "private chat"),
                "chat": ("главный чат", "основной чат", "chat with april"),
                "tools": ("/tools",),
            }.get(area_id, ())
        ):
            if area_id not in ids:
                ids.append(area_id)
    return ids[:4]


def _interpretation_has_concrete_image_edit(interpretation: Any) -> bool:
    """True only when Interpretation has selected the image-edit path and a source exists."""
    if not isinstance(interpretation, dict):
        return False
    intent = interpretation.get("intent") if isinstance(interpretation.get("intent"), dict) else {}
    visual = interpretation.get("visual") if isinstance(interpretation.get("visual"), dict) else {}
    edit_selected = bool(
        intent.get("image_edit_requested")
        or intent.get("image_operation") == "edit"
        or intent.get("task") == "edit_image"
        or visual.get("edit_required")
    )
    if not edit_selected:
        return False
    requested_outputs = intent.get("requested_outputs")
    if not isinstance(requested_outputs, (list, tuple, set)):
        requested_outputs = interpretation.get("requested_outputs")
    if isinstance(requested_outputs, (list, tuple, set)) and requested_outputs:
        normalized_outputs = {str(value or "").strip().lower().replace("-", "_") for value in requested_outputs}
        image_outputs = {"image", "gallery", "generated_image", "image_gallery"}
        # An edit flag alone is insufficient: the selected plan/interpretation must
        # actually authorize the image renderer. Otherwise site navigation falls back
        # to verified links and SVG instead of disappearing behind an unavailable edit.
        if not normalized_outputs.intersection(image_outputs):
            return False
    if intent.get("source_image_available") is True or visual.get("source_image_available") is True:
        return True
    items = visual.get("items") if isinstance(visual.get("items"), list) else []
    return any(
        isinstance(item, dict)
        and any(
            isinstance(item.get(key), str) and item.get(key).startswith("data:image/")
            for key in ("image_url", "data_uri", "src", "image_data_uri", "_content_data_uri")
        )
        for item in items
    )


def _site_navigation_visual_brief(query: str, referenced_area_ids: Any = None) -> Dict[str, Any]:
    """Return source-verified control/route facts for a schematic SVG, never a screen mockup."""
    low = str(query or "").lower().replace("ё", "е")
    scores = _semantic_site_area_scores(low)
    ids = [area_id for score, area_id in scores if score >= 2.8]
    if isinstance(referenced_area_ids, (list, tuple, set)):
        ids = list(dict.fromkeys([str(item) for item in referenced_area_ids if str(item)] + ids))
    semantic = {"domain": "april_ui", "action": "EXPLAIN_UI_ROUTE", "user_goal": query}
    resolved = _site_semantic_function_targets(query, semantic, ids)
    wanted_function_ids = set(resolved.get("function_ids") or [])
    area_index = {str(item.get("id")): item for item in APRIL_SITE_MAP.get("areas", []) if isinstance(item, dict)}
    route_rows = []
    for area_id in ids[:8]:
        item = area_index.get(area_id)
        path = _text(item.get("path")) if item else ""
        if item and path and "[" not in path and path.lower().rstrip("/") != "/admin-profile":
            route_rows.append({
                "area_id": area_id,
                "label": _text(item.get("label")),
                "path": path,
                "entry": _text(item.get("entry")),
                "position": _text(item.get("position")),
                "steps": list(item.get("steps") or [])[:6],
            })
    controls = []
    for item in APRIL_UI_FUNCTION_CATALOG.get("functions", []):
        if not isinstance(item, dict):
            continue
        item_id = _text(item.get("id"))
        item_areas = {str(value) for value in (item.get("areas") or [])}
        if wanted_function_ids and item_id not in wanted_function_ids:
            continue
        if not wanted_function_ids and ids and not item_areas.intersection(ids):
            continue
        controls.append({
            "function_id": item_id,
            "screen": _text(item.get("screen")),
            "entry": _text(item.get("entry")),
            "position": _text(item.get("position")),
            "control_label": _text(item.get("control")),
            "purpose": _text(item.get("does")),
            "steps": list(item.get("how_to_use") or [])[:7],
            "expected_result": _text(item.get("result")),
            "availability": _text(item.get("availability")),
            "limits": _text(item.get("limits")),
        })
        if len(controls) >= 18:
            break
    return {
        "visual_kind": "SOURCE_DERIVED_CONTROL_MAP",
        "not_a_screenshot": True,
        "source": "APRIL_SITE_MAP + APRIL_UI_FUNCTION_CATALOG, both audited against uploaded aprill-web-main components/routes/handlers",
        "purpose": "Show the actual route and interaction sequence using only verified controls. Never draw or imply a screenshot, mock screen, invented navigation panel or pixel layout.",
        "selected_area_ids": ids[:8],
        "verified_routes": route_rows,
        "verified_controls": controls,
        "visual_rules": [
            "Render a simple route/control flowchart, not a page mockup or screenshot imitation.",
            "Use only the exact labels, relative positions, paths and actions present in verified_controls and verified_routes.",
            "Describe position relationally (under the answer, beside the field, in the profile section); never invent pixel coordinates or unverified screen regions.",
            "Label the SVG: 'Схема по исходникам April — не снимок экрана'.",
            "If the source does not verify a control or its current production availability, say that it is not verified instead of filling the gap.",
        ],
    }


def _site_ui_action_contracts(source: Any) -> List[Dict[str, Any]]:
    """Collect current-turn structured UI actions from Interpretation/action_contract.

    This contract is authoritative for routing. Phrase/alias matching remains only
    a fallback for callers that do not provide the Premium interpretation envelope.
    """
    root = source if isinstance(source, dict) else getattr(source, "intent", {})
    if not isinstance(root, dict):
        root = {}
    sources = [root]
    for key in ("request_structure", "intent", "interpretation"):
        value = root.get(key)
        if isinstance(value, dict):
            sources.append(value)
            nested = value.get("request_structure")
            if isinstance(nested, dict):
                sources.append(nested)
    contracts: List[Dict[str, Any]] = []
    for parent in list(sources):
        for sequence_key in ("question_sequence", "presentation_sequence", "answer_sequence"):
            sequence = parent.get(sequence_key) if isinstance(parent, dict) else None
            if not isinstance(sequence, list):
                continue
            for item in sequence:
                if not isinstance(item, dict):
                    continue
                contract = item.get("action_contract")
                if isinstance(contract, dict):
                    contracts.append(contract)
        contract = parent.get("action_contract") if isinstance(parent, dict) else None
        if isinstance(contract, dict):
            contracts.append(contract)
    unique: List[Dict[str, Any]] = []
    seen = set()
    for contract in contracts:
        action = _text(contract.get("action")).upper()
        domain = _text(contract.get("domain")).lower()
        target = _text(contract.get("target"))
        if domain != "april_ui" and action not in {"EXPLAIN_UI_ROUTE", "GUIDE_ATTACH_IMAGE", "GUIDE_UI_ACTION"}:
            continue
        key = (action, domain, target)
        if key in seen:
            continue
        seen.add(key)
        unique.append(dict(contract))
    return unique


def _site_contract_target_ids(contracts: Any) -> List[str]:
    """Translate semantic action-contract targets into canonical site-map ids."""
    valid = {str(item.get("id")) for item in APRIL_SITE_MAP.get("areas", []) if isinstance(item, dict)}
    result: List[str] = []
    mapping = {
        "response.feedback": ["response-feedback", "chat"],
        "response.share_to_community": ["response-feedback", "chat", "space"],
        "rendered_graph.controls": ["graph-controls", "chat"],
        "chat.side_panels": ["chat", "settings", "history"],
        "chat.free_media_referral": ["chat", "settings"],
        "chat.clear_workspace": ["chat"],
        "chat.paperclip_picker": ["attachments", "chat"],
        "chat.voice_input": ["chat"],
        "chat.composer": ["chat"],
        "rendered_artifact.actions": ["image-controls", "chat"],
        "profile.display_name": ["settings"],
        "profile.settings": ["settings"],
        "profile.language": ["settings"],
        "profile.identifiers": ["settings"],
        "profile.plan": ["settings", "plans"],
        "plans.payment": ["settings"],
        "dialogue_history": ["history"],
        "community.public_post": ["space"],
        "community.invite": ["space"],
        "community.friends": ["space"],
        "community.personal_profile": ["space"],
        "community.post_actions": ["space"],
        "community.private_chat": ["space", "direct"],
        "support.request": ["support"],
        "april.help_information": ["guide"],
        "account.delete": ["deletion"],
        "legal.privacy": ["privacy"],
        "legal.terms": ["terms"],
    }
    for contract in contracts if isinstance(contracts, list) else []:
        ui_navigation = contract.get("ui_navigation") if isinstance(contract.get("ui_navigation"), dict) else {}
        targets = ui_navigation.get("targets") if isinstance(ui_navigation.get("targets"), list) else []
        primary_target = _text(ui_navigation.get("target") or contract.get("target"))
        if primary_target:
            targets = [primary_target, *targets]
        for target in targets:
            target = _text(target)
            for target_prefix, ids in mapping.items():
                if target == target_prefix or target.startswith(target_prefix + "."):
                    for area_id in ids:
                        if area_id in valid and area_id not in result:
                            result.append(area_id)
    return result


def _has_site_ui_action_contract(source: Any) -> bool:
    return bool(_site_ui_action_contracts(source))

def prepare_site_help_interpretation(
    interpretation: Dict[str, Any], query: str, question_sequence: Any = None, recent_context: Any = None
) -> bool:
    """Bind only positively requested April UI help to Interpretation."""
    effective_query, removed_negative_clause = _effective_site_help_query(query)
    if removed_negative_clause and not is_site_help_query(effective_query):
        return False
    if removed_negative_clause:
        query = effective_query
    action_contracts = _site_ui_action_contracts(interpretation)
    referent_ids: List[str] = _site_contract_target_ids(action_contracts)
    contextual_ui_followup = {}
    semantic_nav = _site_navigation_semantics(interpretation)
    semantic_function_resolution = _site_semantic_function_targets(query, semantic_nav, referent_ids)
    # A typed April-UI action from the semantic interpreter is sufficient to
    # enter this help room even when the user's wording does not contain a
    # literal UI keyword (e.g. "how do I zoom this graph?"). The resolver only
    # returns function ids after validating domain=april_ui and an allowed
    # navigation action, so this is not a raw phrase trigger.
    direct_match = bool(action_contracts) or bool(semantic_function_resolution.get("function_ids")) or is_site_help_query(query)
    if semantic_function_resolution.get("area_ids") and not referent_ids and (not _site_full_interface_overview_requested(query)):
        # Broad all-controls requests must remain a complete inventory. Semantic
        # area scores are helpful for a focused question, but must not be promoted
        # to explicit referents that truncate the whole-site route map.
        referent_ids = list(semantic_function_resolution.get("area_ids") or [])
    if not direct_match and not removed_negative_clause:
        contextual_ui_followup = _active_site_ui_followup(interpretation, query, recent_context)
        if contextual_ui_followup:
            referent_ids = list(contextual_ui_followup.get("area_ids") or [])
            direct_match = bool(referent_ids)
    if not direct_match and not removed_negative_clause and _ELLIPTICAL_SITE_FOLLOWUP_RE.search(str(query or "")):
        relation = _text(recent_context.get("relation")).upper() if isinstance(recent_context, dict) else ""
        if relation in {"CONTINUE", "FOLLOWUP", "CONTINUATION"}:
            referent_ids = _referenced_site_area_ids(recent_context)
            direct_match = bool(referent_ids)
    if not direct_match:
        return False
    intent = interpretation.setdefault("intent", {})
    if not isinstance(intent, dict):
        intent = {}
        interpretation["intent"] = intent
    outputs = intent.get("requested_outputs")
    outputs = list(outputs) if isinstance(outputs, (list, tuple, set)) else ["text"]
    source_image_edit = _interpretation_has_concrete_image_edit(interpretation)
    attachment_help = _is_attachment_instruction_query(query) or any(_text(item.get("action")).upper() == "GUIDE_ATTACH_IMAGE" for item in action_contracts)
    navigation_visual_request = (
        _site_navigation_picture_request(query, referent_ids)
        or attachment_help
        or bool(action_contracts)
        or bool(semantic_function_resolution.get("function_ids"))
        or bool(contextual_ui_followup)
    )
    route_picture = navigation_visual_request and not source_image_edit
    explicit_raster_requested = bool(_SITE_EXPLICIT_RASTER_REQUEST_RE.search(str(query or "")))
    # The application source cannot capture the user's live browser. A UI screenshot
    # request must become a grounded SVG map, never a fabricated image of a real screen.
    # Actual pixel-level annotation remains available only when a source screenshot is attached.
    explicit_raster = False
    # Free's source-image edit limitation must not be bypassed by turning an edit
    # request into a newly generated substitute image. SVG route guidance remains available.
    if intent.get("image_edit_restricted") or intent.get("task") == "image_edit_restricted":
        explicit_raster = False
    visual = interpretation.get("visual")
    if not isinstance(visual, dict):
        visual = {}
        interpretation["visual"] = visual
    if navigation_visual_request and (source_image_edit or intent.get("image_edit_restricted") or intent.get("task") == "image_edit_restricted"):
        # Pass the map into the authorized image-edit path, or provide an SVG fallback
        # if this plan deliberately removes image output. Never suppress all visual guidance.
        visual["site_navigation_visual_brief"] = _site_navigation_visual_brief(query, referent_ids)
        visual["site_navigation_annotation"] = True
    if navigation_visual_request and (intent.get("image_edit_restricted") or intent.get("task") == "image_edit_restricted") and not source_image_edit:
        intent["site_navigation_edit_fallback"] = {
            "reason": "source_image_edit_not_available_in_current_plan",
            "message": "Честно объясни, что текущий пакет не разрешает редактировать исходное изображение; не создавай отдельную картинку вместо правки. Дай понятную SVG-схему нужного маршрута и ссылку [Настройки и профиль](/settings), где пользователь может проверить текущий тариф и условия Premium. Не выдумывай отдельную страницу или кнопку покупки, если её нет в подтверждённой карте.",
        }
    if route_picture:
        # UI guidance is always a source-derived SVG route map. Even if the user says
        # "real screenshot", never use an image generator to counterfeit the live UI.
        # Pixel-level arrows are only permitted on an actual screenshot supplied by the user.
        if explicit_raster:
            if "image" not in outputs:
                outputs.append("image")
            intent["wants_image"] = True
            intent["explicit_generation_request"] = True
            if isinstance(visual, dict):
                visual["generation_required"] = True
                visual["wants_image"] = True
                visual["site_navigation_visual_brief"] = _site_navigation_visual_brief(query, referent_ids)
        else:
            outputs = [output for output in outputs if str(output).lower().replace("-", "_") not in {"image", "gallery", "generated_image", "image_gallery"}]
            intent["wants_image"] = False
            intent["explicit_generation_request"] = False
            intent["image_operation"] = "none"
            if isinstance(visual, dict):
                visual["generation_required"] = False
                visual["wants_image"] = False
                visual["generator"] = ""
                visual["image_model"] = ""
    wants_diagram = _site_should_render_diagram(query, outputs) and not source_image_edit
    if source_image_edit:
        # The image edit is the requested visual deliverable; keep text and verified
        # route links, but don't add a redundant UI diagram unless explicitly requested.
        explicitly_requested_diagram = bool(_SITE_EXPLICIT_DIAGRAM_RE.search(query))
        wants_diagram = explicitly_requested_diagram
        if not wants_diagram:
            outputs = [value for value in outputs if str(value).lower().replace("-", "_") not in {"diagram", "svg", "schematic", "flowchart", "scene", "layout", "visual", "renderer_scene", "experimental_diagram"}]
    if "text" not in outputs:
        outputs.insert(0, "text")
    if wants_diagram and "diagram" not in outputs:
        outputs.append("diagram")
    if not wants_diagram:
        diagram_aliases = {"diagram", "svg", "schematic", "flowchart", "scene", "layout", "visual", "renderer_scene", "experimental_diagram"}
        outputs = [output for output in outputs if str(output).lower().replace("-", "_") not in diagram_aliases]
    intent["requested_outputs"] = outputs
    intent["wants_diagram"] = wants_diagram
    intent["site_navigation_help"] = True
    intent["site_navigation_contracts"] = action_contracts[:8]
    intent["site_navigation_target_ids"] = list(referent_ids)
    if semantic_function_resolution.get("function_ids"):
        intent["site_navigation_target_functions"] = list(semantic_function_resolution.get("function_ids") or [])
        intent["site_navigation_semantic_targets"] = list(semantic_function_resolution.get("semantic_targets") or [])
    if contextual_ui_followup:
        intent["site_navigation_context_followup"] = True
        intent["site_navigation_target_functions"] = list(contextual_ui_followup.get("function_ids") or [])
        intent["site_navigation_semantic_targets"] = list(contextual_ui_followup.get("semantic_targets") or [])
        intent["site_navigation_context_source"] = "selected_active_dialogue_branch"
    intent["adaptive_visual_policy"] = True
    if explicit_raster_requested and not source_image_edit:
        intent["real_screenshot_unavailable"] = True
        intent["real_screenshot_policy"] = (
            "The service has source code and a verified route/control catalog, but no captured image of the user's current browser screen. "
            "Return a clearly labelled source-derived SVG map, explain that it is a scheme rather than a screenshot, "
            "and ask the user to attach the actual screenshot for pixel-level annotation. Never call the raster image generator for this purpose."
        )
        if isinstance(visual, dict):
            visual["site_navigation_visual_brief"] = _site_navigation_visual_brief(query, referent_ids)
            visual["generation_required"] = False
            visual["wants_image"] = False
            visual["generator"] = ""
            visual["image_model"] = ""
    caps = interpretation.get("routing_capabilities")
    caps = list(caps) if isinstance(caps, (list, tuple, set)) else []
    for capability in ("april_site_help", "site_navigation", "user_guidance"):
        if capability not in caps:
            caps.append(capability)
    if wants_diagram:
        for capability in ("diagram", "geometry"):
            if capability not in caps:
                caps.append(capability)
    else:
        caps = [capability for capability in caps if str(capability).lower() not in {"diagram", "geometry"}]
    interpretation["routing_capabilities"] = caps
    if referent_ids:
        interpretation["site_navigation_referent"] = referent_ids
    interpretation["site_navigation_diagram_policy"] = {
        "enabled": wants_diagram,
        "role": "complement the written navigation instructions",
        "required_payload": "readable responsive SVG plus concrete nodes and directed edges",
        "derive_nodes_from_query_relevant_map_routes": True,
        "route_selection_source": "typed_interpretation_action_contract_then_semantic_site_map",
        "show_relative_control_positions": True,
        "screen_fidelity": "do not create screen mockups; use only APRIL_SITE_MAP routes and APRIL_UI_FUNCTION_CATALOG controls with relational positions",
        "annotate_existing_source_image_when_authorized": True,
        "requested_arrow_colour_is_exact": True,
        "one_diagram_per_logical_stage_only": True,
        "split_long_routes_into_sequential_non_repeating_stages": True,
        "never_emit_empty_diagram_shell": True,
        "use_only_map_routes": True,
        "real_screenshot_not_available_from_source_code": True,
        "svg_label_must_state_not_a_real_screenshot": True,
        "annotate_actual_screenshot_only_if_user_uploaded_source_image": True,
        "never_call_raster_image_generator_to_imitate_live_april_ui": True,
    }
    if isinstance(question_sequence, list):
        for item in question_sequence:
            if not isinstance(item, dict):
                continue
            step_outputs = item.get("output_types")
            step_outputs = list(step_outputs) if isinstance(step_outputs, (list, tuple, set)) else ["text"]
            if "text" not in step_outputs:
                step_outputs.insert(0, "text")
            if wants_diagram and "diagram" not in step_outputs:
                step_outputs.append("diagram")
            if not wants_diagram:
                diagram_aliases = {"diagram", "svg", "schematic", "flowchart", "scene", "layout", "visual", "renderer_scene", "experimental_diagram"}
                step_outputs = [output for output in step_outputs if str(output).lower().replace("-", "_") not in diagram_aliases]
            if route_picture:
                if not explicit_raster:
                    step_outputs = [output for output in step_outputs if str(output).lower().replace("-", "_") not in {"image", "gallery", "generated_image", "image_gallery"}]
                elif "image" not in step_outputs:
                    step_outputs.append("image")
                if "diagram" not in step_outputs:
                    step_outputs.append("diagram")
                item["outputs"] = step_outputs
            item["output_types"] = step_outputs
            item["history_request"] = False if route_picture else item.get("history_request", False)
            if isinstance(item.get("dialogue_search"), dict) and route_picture:
                item["dialogue_search"]["history_request"] = False
                item["dialogue_search"]["search_scope"] = "CURRENT_DIALOGUE"
    structure = interpretation.get("request_structure")
    if isinstance(structure, dict):
        structure["site_navigation_help"] = True
        structure["site_navigation_diagram_required"] = wants_diagram
        if contextual_ui_followup:
            structure["site_navigation_context_followup"] = True
            structure["site_navigation_target_functions"] = list(contextual_ui_followup.get("function_ids") or [])
            structure["site_navigation_semantic_targets"] = list(contextual_ui_followup.get("semantic_targets") or [])
        if route_picture:
            structure["history_request"] = False
            structure["requested_outputs"] = ["text", "diagram", *(["image"] if explicit_raster else [])]
            for sequence_key in ("question_sequence", "presentation_sequence", "answer_sequence"):
                seq = structure.get(sequence_key)
                if isinstance(seq, list):
                    for item in seq:
                        if not isinstance(item, dict):
                            continue
                        key = "output_types" if "output_types" in item or sequence_key == "question_sequence" else "outputs"
                        child_outputs = item.get(key) if isinstance(item.get(key), list) else ["text"]
                        if not explicit_raster:
                            child_outputs = [value for value in child_outputs if str(value).lower().replace("-", "_") not in {"image", "gallery", "generated_image", "image_gallery"}]
                        elif "image" not in child_outputs:
                            child_outputs.append("image")
                        if "text" not in child_outputs: child_outputs.insert(0, "text")
                        if "diagram" not in child_outputs: child_outputs.append("diagram")
                        item[key] = child_outputs
    if route_picture:
        if not explicit_raster:
            intent["task"] = "answer_request" if intent.get("task") in {"generate_image", "create_image", "image_generation"} else intent.get("task", "answer_request")
            intent["wants_image"] = False
            intent["requested_outputs"] = ["text", "diagram"]
        else:
            intent["wants_image"] = True
            intent["explicit_generation_request"] = True
            intent["requested_outputs"] = ["text", "diagram", "image"]
        intent["wants_diagram"] = True
    return True


def _current_user_query(machine_request: Any) -> str:
    """Extract the current user text before generic orchestration goals or history."""
    if isinstance(machine_request, dict):
        root = machine_request
        conversation = root.get("conversation") if isinstance(root.get("conversation"), dict) else {}
        sources = [root, conversation]
        fallback_goal = root.get("goal")
    else:
        conversation = getattr(machine_request, "conversation", {})
        conversation = conversation if isinstance(conversation, dict) else {}
        sources = [conversation]
        fallback_goal = getattr(machine_request, "goal", "")

    current_keys = ("current_request", "current_text", "query", "user_message", "message", "resolved_request")
    # Never let `goal='answer_user_request'` mask the actual message. This was the
    # reason the room could be selected but still receive no request-scoped site map.
    for source in sources:
        if not isinstance(source, dict):
            continue
        for key in current_keys:
            value = source.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()[:1200]
    if isinstance(fallback_goal, str) and fallback_goal.strip() and fallback_goal.strip().lower() not in {
        "answer_user_request", "answer request", "new request", "user request"
    }:
        return fallback_goal.strip()[:1200]
    return ""


def _select_site_map_excerpt(machine_request: Any) -> Dict[str, Any]:
    """Return only routes relevant to the positive, current UI-help request."""
    effective_query, _removed_negative_clause = _effective_site_help_query(_current_user_query(machine_request))
    query = effective_query.lower().replace("ё", "е")
    selected_ids: list[str] = []
    semantic_scores = _semantic_site_area_scores(query)
    matched_cases = APRIL_UI_HELP_QUERY_INDEX.get(_normalize_site_catalog_phrase(query), [])
    # Combine broad semantic similarity with route hints. Hints can clarify a
    # short UI noun, while map metadata permits paraphrases absent from a trigger list.
    score_by_id = {area_id: score for score, area_id in semantic_scores}
    attachment_help = _is_attachment_instruction_query(query)
    feedback_help = bool(re.search(
        r"(?:отблагодар\w*|поблагодар\w*|кнопк\w*\s+(?:спасибо|жалоб)|(?:все|три)\s+кнопк\w*.{0,55}(?:под\s+(?:ответ|сообщен)|under\s+(?:the\s+)?(?:answer|reply))|пожалова\w*.{0,80}(?:ответ|кноп|куда|где)|feedback\s+button|report\s+(?:button|response))",
        query, re.I | re.S,
    )) and bool(re.search(r"(?:куда.{0,40}наж|где.{0,60}(?:кноп|наход|это)|покажи.{0,50}(?:где|куда|путь)|как.{0,30}(?:это|так|сделать|поблагодар)|расскажи.{0,35}покажи|where.{0,50}(?:click|button|find))", query, re.I | re.S))
    direct_hint_ids = [area_id for area_id, hints in _SITE_AREA_HINTS.items() if any(hint in query for hint in hints)]
    if feedback_help:
        selected_ids = ["response-feedback", "chat"]
        direct_hint_ids = ["response-feedback", "chat"]
    for area_id in direct_hint_ids:
        score_by_id[area_id] = max(score_by_id.get(area_id, 0.0), 3.0)
    selected_ids = [area_id for score, area_id in semantic_scores if score_by_id.get(area_id, score) >= 2.8]
    for area_id in direct_hint_ids:
        if area_id not in selected_ids:
            selected_ids.append(area_id)
    if feedback_help:
        # Specific response-rating controls must outrank generic "complaint" -> support.
        selected_ids = ["response-feedback", "chat"]
    # The picker is a modal over /, but its own map node is required so the answer
    # explains the exact attachment workflow rather than generic image controls.
    if attachment_help:
        selected_ids = ["attachments", "chat"]
    elif any(phrase in query for phrase in _SITE_CONCEPT_ALIASES.get("attachments", ())):
        selected_ids = ["attachments", "chat", *[value for value in selected_ids if value not in {"attachments", "chat"}]]
    intent_sources = _site_request_intent_layers(machine_request)
    intent = intent_sources[0] if intent_sources else {}
    ui_action_contracts = _site_ui_action_contracts(machine_request)
    contract_targets = _site_contract_target_ids(ui_action_contracts)
    semantic_ui_targets: list[str] = []
    for _contract in ui_action_contracts:
        _navigation = _contract.get("ui_navigation") if isinstance(_contract.get("ui_navigation"), dict) else {}
        for _target in [_contract.get("target"), *(_navigation.get("targets") if isinstance(_navigation.get("targets"), list) else [])]:
            _target = _text(_target)
            if _target and _target not in semantic_ui_targets:
                semantic_ui_targets.append(_target)
    carried_targets: List[str] = []
    carried_function_ids: List[str] = []
    for source in intent_sources:
        values = source.get("site_navigation_semantic_targets") if isinstance(source.get("site_navigation_semantic_targets"), list) else []
        for value in values:
            value = _text(value)
            if value and value not in carried_targets:
                carried_targets.append(value)
        values = source.get("site_navigation_target_functions") if isinstance(source.get("site_navigation_target_functions"), list) else []
        for value in values:
            value = _text(value)
            if value and value not in carried_function_ids:
                carried_function_ids.append(value)
    semantic_resolved = _site_semantic_function_targets(query, _site_navigation_semantics(machine_request), selected_ids)
    for value in semantic_resolved.get("semantic_targets", []):
        if value not in carried_targets:
            carried_targets.append(value)
    for value in semantic_resolved.get("function_ids", []):
        if value not in carried_function_ids:
            carried_function_ids.append(value)
    for _target in carried_targets:
        if _target and _target not in semantic_ui_targets:
            semantic_ui_targets.append(_target)
    target_function_ids = carried_function_ids
    # A typed answer-feedback action belongs to controls beneath the response,
    # not to the general Contact Support ticket page even when the user says "жалоба".
    if "response-feedback" in contract_targets:
        feedback_help = True
    referent_ids: List[str] = []
    for source in intent_sources:
        for key in ("site_navigation_referent", "site_navigation_target_ids"):
            values = source.get(key) if isinstance(source.get(key), list) else []
            for value in values:
                value = str(value)
                if value not in referent_ids:
                    referent_ids.append(value)
    for value in semantic_resolved.get("area_ids", []):
        # Area scores are provisional navigation suggestions, not explicit
        # referents. A whole-site request must keep the complete route inventory.
        if value not in referent_ids and (not _site_full_interface_overview_requested(query)):
            referent_ids.append(value)
    referent_ids = [value for value in referent_ids if value in {str(area.get("id")) for area in APRIL_SITE_MAP["areas"]}]
    if referent_ids:
        selected_ids = referent_ids + [area_id for area_id in selected_ids if area_id not in referent_ids and area_id != "guide"]
    if not selected_ids:
        selected_ids = ["guide", "chat", "settings", "history"]
    # Target route order follows the user's wording. The uploaded profile image
    # is one user-provided example; the complete route/control inventory comes from Web handlers.
    if not referent_ids and selected_ids and not feedback_help:
        targets = [area_id for area_id in selected_ids if area_id not in {"settings", "chat", "guide", "memory"}]
        targets.sort(key=lambda area_id: min((query.find(hint) for hint in _SITE_AREA_HINTS.get(area_id, ()) if query.find(hint) >= 0), default=10**6))
        if targets and any(area_id in {"history", "space", "support"} for area_id in targets):
            selected_ids = ["settings"] + targets + [area_id for area_id in selected_ids if area_id not in {"settings", *targets, "guide", "memory"}]
    broad_self_help = bool(re.search(
        r"(?:\b(?:april|април)\b.{0,100}\b(?:функци\w*|возможност\w*|устроен\w*|работа\w*|создан\w*|умеешь|умеет|можешь|может)\b|"
        r"\b(?:функци\w*|возможност\w*|устроен\w*|как\s+работа\w*|как\s+устроен\w*)\b.{0,100}\b(?:april|април)\b|"
        r"(?:what can april do|how does april work|how is april built))",
        query,
        re.IGNORECASE,
    ))
    meta_overview_query = bool(re.search(
        r"(?:\bapi\b|\bendpoint\b|\broute\b|api-?шлюз|маршрут api|архитектур\w*|пайплайн|цепочк\w*|"
        r"какие\s+комнат\w*|список\s+комнат|room\s+directory|внутренн\w*\s+комнат|"
        r"кто\s+создал|создател\w*|разработчик\w*|кто\s+автор|автор\s+april|кто\s+владелец)",
        query, re.IGNORECASE,
    ))
    if meta_overview_query and not re.search(
        r"(?:истори\w*\s+диалог\w*|сообществ\w*|community|техподдерж\w*|поддержк\w*|"
        r"настройк\w*|профил\w*|april\s+id|premium\s+id|удален\w*\s+аккаунт|privacy\s+policy|terms\s+of\s+service)",
        query, re.IGNORECASE,
    ):
        broad_self_help = True
    search_availability_target = _site_search_availability_target(query)
    full_interface_overview = _site_full_interface_overview_requested(query)
    if full_interface_overview:
        broad_self_help = True
    elif contract_targets:
        # Typed semantic targets are more reliable than incidental noun overlap
        # (e.g. "language" and "April ID" must not summon unrelated sections).
        selected_ids = list(contract_targets)
    # Specific destinations are resolved from meaning-bearing entities first;
    # generic words such as "куда нажать" must not pull support/chat/help into an
    # otherwise single-destination route. The full site map remains available for
    # broad self-help questions, while this diagram stays request-scoped.
    destination_patterns = {
        "history": r"(?:истори\w*(?:\s+диалог\w*)?|saved\s+dialogues?|previous\s+conversation|прошл\w*\s+диалог\w*|стар\w*\s+бесед\w*|продолж\w*\s+(?:стар\w*\s+)?диалог\w*)",
        "space": r"(?:сообществ\w*|community|публичн\w*\s+чат\w*)",
        "support": r"(?:техподдерж\w*|поддержк\w*|contact\s+support|support\s+(?:ticket|request)|пожаловаться|сообщить\s+об\s+ошибке)",
        "deletion": r"(?:удален\w*\s+аккаунт\w*|account\s+deletion|delete\s+(?:my\s+)?account)",
        "privacy": r"(?:политик\w*\s+конфиденциальност\w*|privacy\s+policy)",
        "terms": r"(?:услови\w*\s+использован\w*|terms\s+of\s+service)",
        "plans": r"(?:тариф\w*|стоимост\w*\s+premium|цена\s+premium|plans\s*(?:&|and)\s*payments|продл\w*\s+premium)",
        "settings": r"(?:настройк\w*|личн\w*\s+кабинет|профил\w*|april\s+id|premium\s+id|settings|profile)",
        "memory": r"(?:памят\w*|memory\b)",
        "chat": r"(?:основн\w*\s+чат|chat\s+with\s+april|главн\w*\s+чат)",
        "guide": r"(?:help\s*(?:&|and)\s*information|справк\w*|центр\s+помощи|help\s+center|how\s+to\s+use\s+april)",
    }
    specific_targets = []
    for area_id, pattern in destination_patterns.items():
        match = re.search(pattern, query, re.IGNORECASE)
        if match:
            specific_targets.append((match.start(), area_id))
    specific_targets.sort(key=lambda item: item[0])
    specific_ids = [area_id for _, area_id in specific_targets]
    entry_request = bool(re.search(
        r"(?:где.{0,50}(?:вход|кнопк|ссылк)|куда\s+нажать|как\s+(?:попасть|перейти|открыть|зайти)|"
        r"покажи.{0,70}(?:куда|путь|стрелк)|из\s+профил|быстрый\s+переход|quick\s+link|from\s+(?:the\s+)?profile)",
        query, re.IGNORECASE,
    ))
    quick_link_targets = {"history", "space", "support", "plans", "deletion"}
    if specific_ids and not broad_self_help and not referent_ids:
        if contract_targets:
            # The typed semantic action contract carries every requested destination.
            # Keep its multi-target route (e.g. public Community post + private chat)
            # instead of replacing it with the first noun-only page match.
            selected_ids = list(dict.fromkeys([*contract_targets, *specific_ids]))
        elif entry_request and set(specific_ids).intersection(quick_link_targets):
            # The supplied profile screenshot shows History, Community and Support
            # as quick links under CURRENT PLAN; display that gateway + destinations.
            selected_ids = ["settings"] + [value for value in specific_ids if value != "settings"]
        else:
            selected_ids = specific_ids
    if broad_self_help and not referent_ids:
        # The screenshot-confirmed CURRENT PLAN panel has four profile shortcuts.
        # The Help & Information page is shown as a second, separate screen below.
        selected_ids = ["chat", "settings", "history", "support", "space", "guide"]
    if full_interface_overview and not referent_ids:
        # Explicit whole-site requests need the complete user-facing map, not the
        # short conversational entry-point map. The admin-only route is excluded.
        selected_ids = [
            "chat", "attachments", "image-controls", "settings", "history", "memory",
            "space", "direct", "support", "guide", "help-center", "how-to-use",
            "plans", "deletion", "privacy", "terms", "tools",
        ]
    elif search_availability_target == "global":
        # No global search exists in this snapshot: show only the one real search surface.
        selected_ids = ["space"]
        referent_ids = ["space"]
    elif search_availability_target == "history":
        # The History page has cards and continuation, but no search box.
        selected_ids = ["history", "chat"]
        referent_ids = ["history"]

    # Exact query-catalog matches are a route regression corpus, not a reason to
    # discard the user's requested destination. Earlier broad capability wording
    # (e.g. the word "April" inside "How to Use April") could accidentally expand
    # a single-page question into the whole site. Keep the named route focused.
    # A literal tariff/price question is the exception: open Plans & Payments while
    # retaining the feature route so the answer can explain both plan and feature.
    if matched_cases and not referent_ids and not meta_overview_query and (not _site_full_interface_overview_requested(query)):
        exact_case = matched_cases[0]
        exact_area = str(exact_case.get("area_id") or "") if isinstance(exact_case, dict) else ""
        known_area_ids = {str(area.get("id")) for area in APRIL_SITE_MAP.get("areas", []) if isinstance(area, dict)}
        if exact_area in known_area_ids:
            plans_question = bool(re.search(
                r"(?:какой\s+(?:тариф|план)|тариф\w*|стоимост\w*|цен\w*\s+(?:premium|подписк)|"
                r"how\s+much|which\s+plan|plan\s+needed|plans?\s*(?:&|and)\s*payments|renew\s+premium)",
                query, re.IGNORECASE,
            ))
            if plans_question:
                selected_ids = ["plans"] + ([exact_area] if exact_area != "plans" else [])
            elif entry_request and exact_area in quick_link_targets:
                selected_ids = ["settings", exact_area]
            else:
                selected_ids = [exact_area]
            broad_self_help = False

    # Feedback buttons are embedded under a reply. Keep the route excerpt focused;
    # never turn the word "жалоба" into the unrelated Support page shortcut.
    if feedback_help and not referent_ids:
        selected_ids = ["response-feedback", "chat"]
        broad_self_help = False
        full_interface_overview = False
    # Add directly related routes so users can recover to the next useful section.
    areas_by_id = {str(area.get("id")): area for area in APRIL_SITE_MAP["areas"]}
    pending = list(selected_ids)
    for area_id in list(selected_ids):
        area = areas_by_id.get(area_id, {})
        for related in area.get("related", []):
            if related in areas_by_id and related not in pending and len(pending) < 5:
                pending.append(related)
    # Specific route questions get only the profile gateway and requested destinations;
    # do not clutter their diagram with unrelated related routes such as Memory or Support.
    query_targets = [area_id for area_id in selected_ids if area_id in {"settings", "chat", "attachments", "image-controls", "graph-controls", "history", "memory", "space", "direct", "support", "guide", "help-center", "how-to-use", "plans", "deletion", "privacy", "terms", "tools", "response-feedback"}]
    if contract_targets or any(area_id not in {"settings", "chat", "guide"} for area_id in query_targets):
        pending = query_targets
    else:
        pending = query_targets + [area_id for area_id in pending if area_id not in query_targets]
    # Button help is an in-message interaction, not a tour of profile/help/history.
    # Force a tiny deterministic excerpt after related-route expansion so a word
    # such as "жалоба" cannot drag generic Support or unrelated pages into the map.
    if "plans.payment" in semantic_ui_targets and not referent_ids:
        pending = ["settings"]
    if feedback_help and not referent_ids:
        pending = ["response-feedback", "chat"]
    if "response.share_to_community" in semantic_ui_targets:
        pending = ["response-feedback", "chat", "space"]
        selected_ids = ["response-feedback", "chat", "space"]
        feedback_help = False
    elif "community.public_post" in semantic_ui_targets:
        pending = ["space"]
        selected_ids = ["space"]
        feedback_help = False
    chosen = [areas_by_id[area_id] for area_id in pending if area_id in areas_by_id]
    selected_ids_final = [str(area.get("id")) for area in chosen]
    screen_id = _site_screen_for_query(query, selected_ids_final, semantic_ui_targets)
    # No screen mockups are returned; all visual guidance comes from the verified control catalog.
    return {
        "schema": APRIL_SITE_MAP["schema"],
        "source": APRIL_SITE_MAP["source"],
        "matched_query": query[:240],
        "areas": chosen[:18] if full_interface_overview else chosen[:7],
        "user_journeys": _select_user_journeys(query),
        "access_matrix": APRIL_ACCESS_MATRIX,
        "screen_id": screen_id,
        "screen_blueprints": [],
        "target_function_ids": target_function_ids[:8],
        "semantic_targets": semantic_ui_targets[:8],
        "context_followup": any(bool(source.get("site_navigation_context_followup")) for source in intent_sources),
        "context_source": next((_text(source.get("site_navigation_context_source")) for source in intent_sources if source.get("site_navigation_context_source")), ""),
        "broad_self_help": bool((broad_self_help or full_interface_overview) and not referent_ids),
        "full_interface_overview": bool(full_interface_overview and not referent_ids),
        "matched_query_cases": [{"case_id": item.get("case_id"), "intent_family": item.get("intent_family"), "expected_path": item.get("expected_path"), "expected_outputs": list(item.get("expected_outputs") or [])} for item in matched_cases[:3]],
        "query_catalog_version": "april.ui.help.catalog.2048.v1",
        "query_catalog_case_count": APRIL_UI_HELP_QUERY_CASE_COUNT,
        "navigation_policy": APRIL_SITE_MAP["navigation_policy"][:4],
        "map_area_count": len(APRIL_SITE_MAP["areas"]),
    }


def _site_screen_for_query(query: str, selected_area_ids: Any = None, semantic_targets: Any = None) -> str:
    """Choose a source-faithful UI screen using the typed Interpretation target first."""
    low = str(query or "").lower().replace("ё", "е")
    ids = {str(value) for value in (selected_area_ids or [])} if isinstance(selected_area_ids, (list, tuple, set)) else set()
    semantic = {str(value) for value in (semantic_targets or [])} if isinstance(semantic_targets, (list, tuple, set)) else set()
    if "response.share_to_community" in semantic:
        return "response-share-community"
    if "rendered_graph.controls" in semantic or "graph-controls" in ids:
        return "graph-controls"
    if "chat.side_panels" in semantic:
        return "chat-side-panels"
    if "chat.free_media_referral" in semantic:
        return "free-media-referral"
    if "plans.payment" in semantic:
        return "plans-payment"
    if "profile.identifiers" in semantic:
        return "profile-identifiers"
    if "profile.language" in semantic:
        return "profile-language"
    if "profile.display_name" in semantic:
        return "profile-name"
    if "chat.voice_input" in semantic:
        return "chat-voice"
    if "chat.clear_workspace" in semantic:
        return "chat-clear"
    if "chat.composer" in semantic:
        return "chat-text"
    if {"community.public_post", "community.private_chat"}.issubset(semantic):
        return "community-flow"
    if "community.private_chat" in semantic:
        return "direct"
    if "community.invite" in semantic:
        return "community-invite"
    if "community.friends" in semantic:
        return "community-friends"
    if "community.personal_profile" in semantic:
        return "community-profile"
    if "community.post_actions" in semantic:
        return "community-post-actions"
    if "community.public_post" in semantic:
        return "community-post"
    # Profile/CURRENT PLAN is the real gateway for known shortcuts, but use it only
    # when the user asks where to enter/click or requests a multi-destination map.
    # A request about continuing a saved dialogue should show the History screen.
    entry_request = bool(re.search(
        r"(?:где.{0,50}(?:вход|кнопк|ссылк|истори|сообществ|поддержк)|куда\s+нажать|как\s+(?:попасть|перейти|открыть|зайти)|"
        r"покажи.{0,70}(?:куда|путь|стрелк)|из\s+профил|быстрый\s+переход|quick\s+link|from\s+(?:the\s+)?profile)",
        low, re.IGNORECASE,
    ))
    shortcut_targets = ids.intersection({"history", "space", "support", "plans", "deletion", "privacy", "terms", "guide", "help-center", "how-to-use"})
    if _site_full_interface_overview_requested(low):
        return "overview"
    if "response-feedback" in ids or (re.search(r"(?:отблагодар\w*|поблагодар\w*|кнопк\w*\s+(?:спасибо|жалоб)|пожалова\w*)", low, re.I) and re.search(r"(?:куда.{0,35}наж|где.{0,60}(?:кноп|наход)|покажи.{0,50}(?:где|куда)|как.{0,30}(?:это|так|сделать|поблагодар)|расскажи.{0,35}покажи)", low, re.I | re.S)):
        return "response-feedback"
    if "attachments" in ids:
        return "attachments"
    if "image-controls" in ids:
        return "artifact-actions"
    if "settings" in ids and shortcut_targets and (entry_request or len(shortcut_targets) > 1):
        return "profile"
    # A source-image annotation is handled by the image-edit branch, not this screen map.
    if any(term in low for term in ("скрепк", "прикреп", "вложен", "камера", "изображения", "файлы", "camera", "attachment", "file picker", "upload")):
        return "attachments"
    if ids.intersection({"guide", "help-center", "how-to-use", "privacy", "terms"}) or any(term in low for term in ("help & information", "справка", "центр помощи", "privacy policy", "terms of service", "how to use april")):
        return "help"
    if "space" in ids and "direct" in ids:
        public_post_action = bool(re.search(
            r"(?:публичн\w*\s+(?:пост|сообщени)|пост\w*\s+в\s+сообществ|публикац\w*|файл\w*.{0,45}в\s+сообществ|send.{0,35}to\s+(?:the\s+)?community)", low, re.I
        ))
        private_message_action = bool(re.search(
            r"(?:личн\w*\s+чат|приватн\w*\s+чат|private\s+chat|отправ\w*.{0,45}друг\w*|пересл\w*.{0,45}друг\w*)", low, re.I
        ))
        if public_post_action and private_message_action:
            return "community-flow"
    if "direct" in ids and re.search(r"(?:личн\w*\s+чат|private\s+chat|друг\w*.{0,60}(?:отправ\w*|пересл\w*|подел\w*))", low, re.I):
        return "direct"
    if "space" in ids or "direct" in ids or any(term in low for term in ("сообществ", "community", "private chat", "публичн", "участник", "пост пользователя")):
        return "community"
    if "deletion" in ids:
        return "deletion"
    if "history" in ids or any(term in low for term in ("saved dialogues", "история диалогов", "старый разговор", "вернуться к переписке")):
        # Show profile only for an entry/shortcut request; content questions about
        # resuming/locating a saved thread should show the actual History screen.
        return "profile" if "settings" in ids and (entry_request or len(shortcut_targets) > 1) else "history"
    if "settings" in ids or "plans" in ids or any(term in low for term in ("личный кабинет", "профиль", "подписк", "april id", "premium id", "renew", "язык интерфейса")):
        return "profile"
    if "support" in ids or any(term in low for term in ("техподдерж", "contact support", "обращение в поддержку")):
        return "support"
    if "chat" in ids:
        return "chat"
    return "profile" if ids else "help"


def _site_help_requested(machine_request: Any) -> bool:
    raw_query = _current_user_query(machine_request)
    query, removed_negative_clause = _effective_site_help_query(raw_query)

    # Current-turn structured interpretation is authoritative. A rejected/negated
    # UI clause cannot be revived by a stale contract from an earlier turn.
    if query and is_site_help_query(query):
        return True
    if removed_negative_clause:
        return False
    if query and _has_site_ui_action_contract(machine_request):
        return True

    if query:
        # A follow-up remains in the IT room only if the current turn's semantic
        # Interpretation explicitly inherited a concrete active UI referent.
        if isinstance(machine_request, dict):
            intent = machine_request.get("intent") if isinstance(machine_request.get("intent"), dict) else machine_request
        else:
            intent = getattr(machine_request, "intent", {})
            intent = intent if isinstance(intent, dict) else {}
        nested = intent.get("interpretation") if isinstance(intent.get("interpretation"), dict) else {}
        nested_intent = intent.get("intent") if isinstance(intent.get("intent"), dict) else {}
        nested_structure = intent.get("request_structure") if isinstance(intent.get("request_structure"), dict) else {}
        nested_dialogue = intent.get("dialogue") if isinstance(intent.get("dialogue"), dict) else {}
        nested_semantics = nested_structure.get("semantic_interpretation") if isinstance(nested_structure.get("semantic_interpretation"), dict) else {}
        nested_features = nested_semantics.get("features") if isinstance(nested_semantics.get("features"), dict) else {}
        if not nested_features and isinstance(nested_semantics.get("intent_features"), dict):
            nested_features = nested_semantics.get("intent_features")
        valid_ids = {str(area.get("id")) for area in APRIL_SITE_MAP.get("areas", []) if isinstance(area, dict)}
        sources = (intent, nested, nested_intent, nested_structure)
        known_function_ids = {
            str(item.get("id")) for item in APRIL_UI_FUNCTION_CATALOG.get("functions", [])
            if isinstance(item, dict) and item.get("id")
        }
        for source in sources:
            inherited = bool(source.get("site_navigation_context_followup"))
            refs = source.get("site_navigation_referent") or source.get("site_navigation_target_ids")
            if inherited and isinstance(refs, list) and any(str(ref) in valid_ids for ref in refs):
                carried_functions = source.get("site_navigation_target_functions")
                carried_functions = carried_functions if isinstance(carried_functions, list) else []
                verified_functions = [str(value) for value in carried_functions if str(value) in known_function_ids]
                context_source = _text(source.get("site_navigation_context_source"))
                # A validated active-branch match may arrive with relation=NEW when
                # the upstream state manager misclassifies an elliptical UI follow-up.
                # Trust only the local C_IT_ROOM resolution with a concrete catalog ID;
                # do not make arbitrary NEW turns inherit stale UI history.
                if context_source == "selected_active_dialogue_branch" and verified_functions:
                    return True
                relation = _text(nested_dialogue.get("relation") or intent.get("dialogue", {}).get("relation") if isinstance(intent.get("dialogue"), dict) else nested_dialogue.get("relation")).upper()
                semantically_contextual = bool(
                    nested_features.get("context_dependent_question")
                    or nested_features.get("previous_assistant_output_reference")
                    or nested_features.get("strong_anaphoric_reference")
                    or _text(nested_semantics.get("primary_intent") or nested_semantics.get("semantic_intent") or nested_semantics.get("intent")).upper() in {"TOPIC_CONTINUATION", "PREVIOUS_ANSWER_FOLLOWUP"}
                )
                if relation in {"CONTINUE", "FOLLOWUP", "CONTINUATION"} and semantically_contextual:
                    return True
        # Backward-compatible path for older serialized interpretations.
        if _ELLIPTICAL_SITE_FOLLOWUP_RE.search(query):
            for source in sources:
                refs = source.get("site_navigation_referent") if isinstance(source, dict) else None
                if isinstance(refs, list) and any(str(ref) in valid_ids for ref in refs):
                    return True
        return False

    # Non-chat/internal callers without a current message may still supply an
    # explicit room capability. It is never allowed to override actual user text.
    if isinstance(machine_request, dict):
        intent = machine_request.get("intent") if isinstance(machine_request.get("intent"), dict) else machine_request
    else:
        intent = getattr(machine_request, "intent", {})
        intent = intent if isinstance(intent, dict) else {}
    nested = intent.get("interpretation") if isinstance(intent.get("interpretation"), dict) else {}
    for source in (intent, nested):
        capabilities = source.get("routing_capabilities") or []
        if isinstance(capabilities, (tuple, list, set)) and set(capabilities).intersection(_SITE_HELP_SIGNALS):
            return True
        if source.get("site_navigation_help") is True:
            return True
    routing = getattr(machine_request, "routing", {}) if not isinstance(machine_request, dict) else machine_request.get("routing", {})
    return bool(isinstance(routing, dict) and routing.get("site_help_requested") is True)



def ensure_site_navigation_response(decoded: Dict[str, Any], machine_request: Any) -> Dict[str, Any]:
    """Deterministically add clickable route links and a source-derived route diagram to UI-help answers.

    This runs after the provider response is decoded but before the canonical SceneContract
    normalizer. It guarantees that navigation help does not depend on the model choosing a
    diagram renderer correctly; the prose answer remains intact and primary.
    """
    if not isinstance(decoded, dict) or not _site_help_requested(machine_request):
        return decoded
    context: Dict[str, Any] = {}
    routing = getattr(machine_request, "routing", {}) if not isinstance(machine_request, dict) else machine_request.get("routing", {})
    if isinstance(routing, dict):
        rooms = routing.get("room_knowledge_context")
        if isinstance(rooms, dict) and isinstance(rooms.get("it"), dict):
            context = rooms["it"]
    if not context:
        context = get_context(machine_request)
    site_map = context.get("site_navigation_map") if isinstance(context, dict) else None
    # Always re-rank the canonical map for the current turn. A full room-map
    # contribution may contain every route; rendering all of it for a one-button
    # request creates a cluttered diagram and steals focus from the requested path.
    request_scoped_map = _select_site_map_excerpt(machine_request)
    if isinstance(request_scoped_map, dict) and isinstance(request_scoped_map.get("areas"), list) and request_scoped_map.get("areas"):
        site_map = request_scoped_map
    if not isinstance(site_map, dict) or not isinstance(site_map.get("areas"), list) or not site_map.get("areas"):
        # The route map is local and deterministic; use it directly if a room
        # contribution was omitted by upstream orchestration instead of silently
        # returning an unstructured navigation answer.
        site_map = _select_site_map_excerpt(machine_request)
    areas = [area for area in (site_map.get("areas") or []) if isinstance(area, dict)]
    if not areas:
        return decoded

    # Build a unique list of safe, known relative routes. Never expose a dynamic
    # placeholder such as /space/direct/[friendId] as a literal clickable URL.
    full_interface_overview = bool(site_map.get("full_interface_overview"))
    route_row_limit = 17 if full_interface_overview else 7
    route_rows: List[Dict[str, str]] = []
    seen_area_ids = set()
    for area in areas:
        area_id = _text(area.get("id"))
        path = _text(area.get("path"))
        label = _text(area.get("label"))
        # The map contains one admin-only reference for architecture/safety context;
        # it must never become a clickable destination for ordinary users.
        if area_id == "admin-support" or path.lower().rstrip("/") == "/admin-profile":
            continue
        if not path or not label or "[" in path or "]" in path:
            if path == "/space/direct/[friendId]":
                path = "/space"
                label = "Личный диалог через сообщество"
            else:
                continue
        if area_id and area_id in seen_area_ids:
            continue
        if area_id:
            seen_area_ids.add(area_id)
        route_rows.append({
            "id": area_id or f"route_{len(route_rows)+1}", "path": path, "label": label,
            "purpose": _text(area.get("purpose")),
            "steps": [str(step).strip() for step in area.get("steps", []) if str(step).strip()] if isinstance(area.get("steps"), list) else [],
        })
        if len(route_rows) >= route_row_limit:
            break
    if not route_rows:
        return decoded

    answer_key = next((key for key in ("answer", "content", "text", "message") if isinstance(decoded.get(key), str) and decoded[key].strip()), "answer")
    answer = _text(decoded.get(answer_key))
    if not answer:
        for block in (decoded.get("render_blocks") if isinstance(decoded.get("render_blocks"), list) else []):
            if not isinstance(block, dict):
                continue
            block_type = _text(block.get("type") or block.get("artifact_type") or "text").lower()
            if block_type in {"text", "markdown", "message", "message_text"}:
                candidate = _text(block.get("content") or block.get("text") or block.get("markdown"))
                if candidate:
                    answer = candidate
                    answer_key = "answer"
                    break
    if not answer:
        return decoded
    language = _text(
        (getattr(machine_request, "constraints", {}) or {}).get("display_language", "")
        if not isinstance(machine_request, dict) else (machine_request.get("constraints") or {}).get("display_language", "")
    ).lower()
    is_ru_or_uk = language.startswith(("ru", "uk")) or not language
    heading = "Проверенные переходы" if is_ru_or_uk else "Verified links"
    effective_route_query, _removed_negative_route_clause = _effective_site_help_query(_current_user_query(machine_request))
    query_for_routes = effective_route_query.lower().replace("ё", "е")
    target_function_ids = site_map.get("target_function_ids") if isinstance(site_map.get("target_function_ids"), list) else []
    contextual_site_followup = bool(site_map.get("context_followup"))
    if "assistant_response_share" in target_function_ids and is_ru_or_uk:
        answer = (
            "Да — зелёная круглая стрелка вверх находится **под каждым ответом April**, рядом с кнопками «Жалоба» и «Спасибо». "
            "Её точная подпись/подсказка в Web: **«Опубликовать в сообществе»**. Это отдельная кнопка публикации именно текущего ответа April, "
            "а не стрелка отправки в нижнем поле чата и не кнопка отправки нового поста в Community.\n\n"
            "1. Найдите ответ April, который хотите опубликовать.\n"
            "2. Проверьте его текст и прикреплённые материалы: публикация попадёт в общую ленту Community.\n"
            "3. Нажмите зелёную круглую стрелку вверх **под этим ответом**. April отправит текст ответа и доступный для публикации материал напрямую; копировать текст вручную и вставлять его в редактор Community не нужно.\n"
            "4. Дождитесь сообщения **«Сообщение отправлено в сообщество.»**; затем откройте [Community / Сообщество](/space), чтобы увидеть публикацию.\n\n"
            "Если публикация не удалась, появится сообщение об ошибке. Вложение публикуется только если оно поддерживается и проходит проверку размера; приватный/непубликуемый материал не должен молча превращаться в публикацию одного текста. "
            "Перед нажатием убедитесь, что в ответе нет личных данных, паролей или ключей API."
        )
        decoded["answer"] = answer
        decoded["content"] = answer
        if answer_key not in {"answer", "content"}:
            decoded[answer_key] = answer
    elif "community_public_post" in target_function_ids and is_ru_or_uk:
        if contextual_site_followup:
            answer = (
                "Зелёная круглая стрелка **«Отправить»** — это кнопка публикации в нижней панели **Community / Сообщество**. "
                "Она отправляет текст, который вы ввели или вставили в поле публикации, и выбранное вложение в общую ленту. "
                "Она **не пересылает автоматически** уже готовый ответ April из основного чата.\n\n"
                "Чтобы опубликовать мой ответ: скопируйте его текст в чате, откройте [Сообщество April](/space), "
                "прокрутите к нижней панели, вставьте текст в поле «Опишите вопрос или поделитесь решением…» и нажмите зелёную стрелку **«Отправить»**. "
                "Публикация станет видна участникам сообщества. Перед отправкой проверьте текст: не добавляйте пароли, ключи API и личные данные.\n\n"
                "Скрепка слева от поля — отдельная необязательная функция «Прикрепить файл»; файл ограничен 3 МБ."
            )
        else:
            answer = (
                "Чтобы разместить мой ответ в общей ленте, сначала скопируйте его текст из основного чата — "
                "в просмотренном исходнике нет отдельной кнопки автоматической пересылки ответа April в Community.\n\n"
                "1. Откройте [Сообщество April](/space) напрямую. Также его можно найти через [Настройки и профиль](/settings) → карточку CURRENT PLAN → **Community / Сообщество**.\n"
                "2. Прокрутите ленту до нижней закреплённой панели. В поле «Опишите вопрос или поделитесь решением…» вставьте скопированный ответ.\n"
                "3. При необходимости нажмите слева **«Прикрепить файл»** и выберите один разрешённый файл до 3 МБ.\n"
                "4. Нажмите справа зелёную круглую стрелку **«Отправить»**. Текст и вложение появятся в общей ленте и будут видны участникам.\n\n"
                "Не публикуйте пароли, ключи API и личные данные. Кнопка Community Send публикует введённый черновик, а не пересылает ответ April автоматически."
            )
        decoded["answer"] = answer
        decoded["content"] = answer
        if answer_key not in {"answer", "content"}:
            decoded[answer_key] = answer
    elif "assistant_response_share" in target_function_ids and not is_ru_or_uk:
        answer = (
            "The green round up-arrow is directly **under each April reply**, beside the Report and Thanks controls. "
            "Its source label is **Share in community**. It publishes that specific April response to the public Community feed; "
            "it is not the Send arrow in the chat composer or the Community post composer.\n\n"
            "1. Find the April reply you want to publish and review its text and attached material.\n"
            "2. Click the green round arrow directly under that reply. April sends the response and any supported shareable material without manual copy/paste.\n"
            "3. Wait for **Message sent to the community.**, then open [Community](/space) to view the post.\n\n"
            "If publication fails, the control shows an error. Attachments must be supported and pass the size check; do not publish personal data, passwords or API keys."
        )
        decoded["answer"] = answer
        decoded["content"] = answer
        if answer_key not in {"answer", "content"}:
            decoded[answer_key] = answer
    elif "community_public_post" in target_function_ids and not is_ru_or_uk:
        if contextual_site_followup:
            answer = (
                "The green round **Send** arrow is the publish button in the fixed bottom composer on **Community**. "
                "It posts the text you typed or pasted, plus any selected attachment, to the public feed. "
                "It does **not** automatically forward an existing April reply from the main chat.\n\n"
                "To post my reply, copy its text in the main chat, open [April Community](/space), scroll to the bottom composer, "
                "paste it into the question field and click the green **Send** arrow. The post is visible to community members. "
                "Do not include passwords, API keys or personal data."
            )
        else:
            answer = (
                "Copy the text of my reply from the main chat first; the inspected source does not contain a one-click control "
                "that automatically forwards an April reply to Community.\n\n"
                "1. Open [April Community](/space), or go through [Profile and Settings](/settings) → CURRENT PLAN → **Community**.\n"
                "2. Scroll to the fixed composer at the bottom and paste the reply into the question field.\n"
                "3. Optionally use **Attach a file** for one supported file up to 3 MB.\n"
                "4. Click the green round **Send** arrow. The post appears in the public feed and is visible to community members. "
                "Never post passwords, API keys or personal data."
            )
        decoded["answer"] = answer
        decoded["content"] = answer
        if answer_key not in {"answer", "content"}:
            decoded[answer_key] = answer
    feedback_help = bool(re.search(
        r"(?:отблагодар\w*|поблагодар\w*|спасибо.{0,45}(?:кноп|где|куда|наж)|пожалова\w*|жалоб\w*|feedback\s+button|report\s+(?:button|response)|thank(?:s|ing)?\s+button)",
        query_for_routes, re.I,
    )) and bool(re.search(r"(?:куда.{0,35}наж|что\s+нажать|где.{0,60}(?:кноп|наход|это)|кноп\w*.{0,60}(?:где|наж)|покажи.{0,60}(?:где|куда|путь)|как.{0,30}(?:это|так|сделать|поблагодар)|расскажи.{0,35}покажи|where.{0,60}(?:click|button|find))", query_for_routes, re.I | re.S))
    if feedback_help:
        if is_ru_or_uk:
            answer = (
                "В основном чате найдите именно тот ответ April, за который хотите оставить отзыв. "
                "Прокрутите до конца этого ответа: сразу под ним находится строка с кнопками «Жалоба» и «Спасибо».\n\n"
                "1. **Чтобы поблагодарить:** нажмите «Спасибо». Появится короткое подтверждение «Спасибо за обратную связь». "
                "Новое сообщение в поле ввода писать не нужно.\n"
                "2. **Чтобы пожаловаться:** нажмите «Жалоба». Откроется форма; выберите причину — вредный ответ, оскорбительный, "
                "вводящий в заблуждение или другое — затем отправьте форму.\n\n"
                "Фото, график или код прикреплять не нужно. Эти кнопки относятся к конкретному ответу и находятся под ним, а не в поле сообщения."
            )
        else:
            answer = (
                "In the main chat, find the specific April reply you want to react to. Scroll to the end of that reply; "
                "the «Report» and «Thanks» buttons are directly underneath it.\n\n"
                "1. To thank April, click «Thanks». A brief feedback confirmation appears; you do not need to type another message.\n"
                "2. To report a problem, click «Report», choose a reason (harmful, offensive, misleading, or other), then submit the form.\n\n"
                "No photo, graph, or code attachment is needed. These controls belong to the reply itself, not the message input."
            )
        decoded["answer"] = answer
        decoded["content"] = answer
        if answer_key not in {"answer", "content"}:
            decoded[answer_key] = answer
    product_walkthrough = bool(re.search(
        r"(?:\b(?:free|бесплатн\w*)\b.{0,70}\b(?:premium|премиум)\b|\b(?:premium|премиум)\b.{0,70}\b(?:free|бесплатн\w*)\b|"
        r"(?:как\s+(?:устроен\w*|работа\w*|пользова\w*)).{0,90}(?:april|април)|"
        r"(?:объясни|расскажи).{0,90}(?:april|април).{0,60}(?:free|premium|премиум|куда\s+нажать)|"
        r"how\s+(?:does|to\s+use)\s+april.{0,100}(?:free|premium|step|click|navigate))",
        query_for_routes, re.IGNORECASE | re.DOTALL,
    )) and bool(re.search(r"(?:объясн|расскаж|покажи|по\s+шагам|пошаг|куда\s+нажать|как\s+польз|how|guide|step[- ]by[- ]step|click)", query_for_routes, re.I)) and not full_interface_overview
    if product_walkthrough:
        if is_ru_or_uk:
            answer = (
                "**Как устроена April: Free и Premium**\n\n"
                "**Free** — основной чат, поддерживаемые вложения, сообщество `/space`, профиль и настройки `/settings`, справка `/aprill`; редактирование исходного изображения доступно за одну бонусную операцию приглашения на каждую правку. По проектной политике активный контекст хранится до 12 часов.\n\n"
                "**Premium** включает функции Free, доступ к сохранённым диалогам `/history` (с проверкой активного Premium), расширенный доступ к поддерживаемым операциям с изображениями и активный контекст до 24 часов. В Free редактирование исходного изображения расходует одну бонусную операцию приглашения на каждую правку. В проверенных исходниках нет основания обещать, что отдельные страницы `/memory` или `/tools` работают как самостоятельные пользовательские разделы.\n\n"
                "**Куда нажимать:**\n"
                "1. [Основной чат April](/) — задавайте вопрос обычным текстом или голосом; прикладывайте файл только если хотите, чтобы April изучила именно этот файл.\n"
                "2. [Настройки и профиль](/settings) — проверьте аккаунт, язык и карточку CURRENT PLAN; в ней находятся быстрые переходы к разделам.\n"
                "3. [Сообщество](/space) — откройте публичное сообщество и доступные в текущем интерфейсе действия с участниками.\n"
                "4. [История диалогов](/history) — Premium: выберите сохранённую запись и нажмите **Continue this dialogue**, чтобы продолжить именно её.\n"
                "5. [Help & Information / Справка](/aprill) — инструкции, условия, конфиденциальность, тарифы и другие карточки справки.\n\n"
                "**Принцип работы:** сначала определяем, что вы хотите сделать, затем выбираем соответствующий раздел и выполняем действия по порядку. Для навигационной подсказки April должна показывать короткую схему маршрута; фотография не требуется, если вопрос не связан с конкретным изображением."
            )
        else:
            answer = (
                "**How April works: Free and Premium**\n\n"
                "**Free** includes the main chat, supported attachments, Community `/space`, Profile and Settings `/settings`, Help `/aprill`, image editing for one invitation-bonus operation per edit, and up to 12 hours of active context under the project policy.\n\n"
                "**Premium** includes Free features, saved-dialogue History `/history` (with an active Premium entitlement check), expanded supported image operations, and up to 24 hours of active context. Free image editing uses one invitation-bonus operation per edit. The source snapshot does not support promising standalone working `/memory` or `/tools` pages.\n\n"
                "**Where to click:**\n"
                "1. [Main April chat](/) — ask in text or voice; attach a file only when you want April to inspect that file.\n"
                "2. [Profile and Settings](/settings) — review your account, language and CURRENT PLAN card.\n"
                "3. [Community](/space) — open the community and use the participant actions available on screen.\n"
                "4. [Dialogue History](/history) — Premium: select a saved conversation and click **Continue this dialogue**.\n"
                "5. [Help & Information](/aprill) — instructions, terms, privacy, plans and help cards.\n\n"
                "April should identify the requested action first, then provide the appropriate destination and ordered steps. A photo is not needed unless the question concerns a specific image."
            )
        decoded["answer"] = answer
        decoded["content"] = answer
        if answer_key not in {"answer", "content"}:
            decoded[answer_key] = answer
    asked_for_real_screenshot = bool(re.search(
        r"(?:реальн\w*.{0,35}(?:скриншот|снимок|экран|интерфейс)|(?:скриншот|снимок).{0,45}(?:реальн\w*|настоящ\w*)|live\s+screenshot|actual\s+screen(?:shot)?|real\s+(?:ui|interface|screenshot))",
        query_for_routes, re.IGNORECASE,
    ))
    screenshot_honesty_note = (
        "Важно: я не вижу захват вашего текущего экрана. Схема ниже построена по проверенным исходникам April и не является настоящим скриншотом. Если нужно поставить стрелки точно на вашем экране, прикрепите его снимок в чат."
        if is_ru_or_uk else
        "Note: I cannot capture your current browser screen from source code. The guide below is a source-derived diagram, not a real screenshot. Attach your screenshot if you need arrows placed on the exact screen."
    )
    # Always expose a safe route back to the main chat. Add it as a text link even
    # when the selected excerpt only contains a deep-link destination.
    if feedback_help and not any(row.get("id") == "chat" for row in route_rows):
        route_rows.insert(0, {"id": "chat", "path": "/", "label": "Основной чат April"})
        route_rows = route_rows[:route_row_limit]
    elif not any(row["path"] == "/" for row in route_rows):
        route_rows.insert(0, {"id": "chat", "path": "/", "label": "Основной чат April"})
        route_rows = route_rows[:route_row_limit]
    missing_links = []
    linked_paths = set(re.findall(r"\]\((/[^)]+)\)", answer))
    seen_missing_paths = set()
    if product_walkthrough:
        walkthrough_route_ids = {"chat", "settings", "space", "history", "guide"}
        route_rows_for_links = [row for row in route_rows if row.get("id") in walkthrough_route_ids]
    else:
        route_rows_for_links = [row for row in route_rows if not feedback_help or row.get("id") == "chat"]
    for row in route_rows_for_links:
        path = row["path"]
        if path not in linked_paths and path not in seen_missing_paths:
            missing_links.append(row)
            seen_missing_paths.add(path)
    if missing_links:
        label_path_pairs = " · ".join(f"[{row['label']}]({row['path']})" for row in missing_links)
        addition = f"\n\n**{heading}:** {label_path_pairs}."
        answer = answer.rstrip() + addition
        decoded["answer"] = answer
        decoded["content"] = answer
        if answer_key not in {"answer", "content"}:
            decoded[answer_key] = answer

    # When a concrete area is named, state its verified route and next actions
    # explicitly. This corrects an LLM-generated "I cannot find this page" claim
    # when the canonical map does contain the destination.
    query_for_routes = _current_user_query(machine_request).lower().replace("ё", "е")
    targeted_ids = [
        area_id for area_id, hints in _SITE_AREA_HINTS.items()
        if any(hint in query_for_routes for hint in hints)
    ]
    if targeted_ids and not feedback_help and not product_walkthrough:
        full_areas = {str(area.get("id")): area for area in APRIL_SITE_MAP.get("areas", []) if isinstance(area, dict)}
        target_area = next((full_areas.get(area_id) for area_id in targeted_ids if full_areas.get(area_id) and area_id != "admin-support"), None)
        if target_area:
            target_path = _text(target_area.get("path"))
            if target_path and "[" not in target_path and "]" not in target_path and target_path.lower().rstrip("/") != "/admin-profile":
                target_label = _text(target_area.get("label")) or "Раздел April"
                target_steps = target_area.get("steps") if isinstance(target_area.get("steps"), list) else []
                safe_steps = [str(step).strip() for step in target_steps if str(step).strip()][:3]
                guide_heading = "Путь по карте April" if heading == "Проверенные переходы" else "Verified route in April"
                route_intro = f"**{guide_heading}:** [{target_label}]({target_path})."
                if safe_steps:
                    route_intro += "\n" + "\n".join(f"{index}. {step}" for index, step in enumerate(safe_steps, 1))
                # Add the deterministic guide when a model misses the path or
                # contradicts the verified map. If a route is already described
                # correctly, leave the model's step sequence unchanged.
                has_target_path = f"]({target_path})" in answer
                contradicts_map = bool(re.search(
                    r"(?:нет[^.\n]{0,140}(?:раздел|экрана|страниц|ссылк|приглашен)|"
                    r"(?:раздел|экран|страниц|ссылк)[^.\n]{0,100}\bнет\b|"
                    r"не\s+могу\s+(?:подтвердить|указать)[^.\n]{0,100}(?:существ|ссылк|путь)|"
                    r"(?:такого|такой)\s+(?:раздела|страницы|ссылки)\s+нет|"
                    r"cannot\s+(?:confirm|find)\s+(?:the\s+)?(?:page|section|link))",
                    answer.lower(),
                ))
                if target_area.get("id") == "space":
                    route_intro += "\nСтраница сообщества указана в проверенной карте сайта; отдельный URL-приглашение в доступной карте не указан."
                if contradicts_map:
                    # Remove only the sentence that denies the verified route; keep
                    # other useful context and let the map-derived route text replace it.
                    denial_sentence = re.compile(
                        r"[^.!?\n]*(?:нет[^.!?\n]{0,140}(?:раздел|экрана|страниц|ссылк|приглашен)|"
                        r"(?:раздел|экран|страниц|ссылк)[^.!?\n]{0,100}\bнет\b|"
                        r"не\s+могу\s+(?:подтвердить|указать)[^.!?\n]{0,100}(?:существ|ссылк|путь)|"
                        r"(?:такого|такой)\s+(?:раздела|страницы|ссылки)\s+нет|"
                        r"cannot\s+(?:confirm|find)\s+(?:the\s+)?(?:page|section|link))[^.!?\n]*[.!?]?",
                        re.IGNORECASE,
                    )
                    corrected = denial_sentence.sub("", answer)
                    corrected = re.sub(r"(?:\n\s*){3,}", "\n\n", corrected).strip()
                    if corrected:
                        answer = corrected
                if not has_target_path or contradicts_map:
                    answer = answer.rstrip() + "\n\n" + route_intro
                    decoded["answer"] = answer
                    decoded["content"] = answer
                    if answer_key not in {"answer", "content"}:
                        decoded[answer_key] = answer

    # For a visual navigation request that names several destinations, provide one ordered
    # how-to sequence in prose as well as the SVG. The route list comes from the actual map
    # and the screenshot-confirmed CURRENT PLAN shortcuts; it is never a generated mock photo.
    if _site_navigation_picture_request(query_for_routes):
        ordered_targets = []
        for area_id, hints in _SITE_AREA_HINTS.items():
            if area_id not in {"space", "history", "support", "chat", "settings", "guide", "plans", "deletion", "privacy", "terms"}:
                continue
            positions = [query_for_routes.find(hint) for hint in hints if query_for_routes.find(hint) >= 0]
            if positions:
                ordered_targets.append((min(positions), area_id))
        ordered_targets = [area_id for _, area_id in sorted(ordered_targets)][:3]
        area_by_id = {str(area.get("id")): area for area in APRIL_SITE_MAP.get("areas", []) if isinstance(area, dict)}
        steps = []
        if any(area_id in {"space", "history", "support"} for area_id in ordered_targets):
            steps.append("Откройте [Настройки и профиль](/settings) — на странице профиля найдите карточку CURRENT PLAN.")
        for area_id in ordered_targets:
            area = area_by_id.get(area_id)
            if not area:
                continue
            route = _text(area.get("path"))
            label = _text(area.get("label"))
            if area_id == "space":
                steps.append(f"Для сообщества нажмите **Community / Сообщество** в карточке CURRENT PLAN или откройте [{label}]({route}).")
            elif area_id == "history":
                steps.append(f"Для истории нажмите **Dialog history / История диалогов** или откройте [{label}]({route}); затем выберите нужную запись и нажмите **Continue this dialogue**.")
            elif area_id == "support":
                steps.append(f"Для поддержки нажмите **Contact support** или откройте [{label}]({route}).")
            elif area_id in {"chat", "guide", "plans", "deletion", "privacy", "terms"} and route:
                steps.append(f"Откройте [{label}]({route}).")
        if steps and not re.search(r"(?:как пройти по интерфейсу|порядок перехода|route steps)", answer, re.IGNORECASE):
            guide = "**Как пройти по интерфейсу:**\n" + "\n".join(f"{index}. {step}" for index, step in enumerate(steps, 1))
            answer = answer.rstrip() + "\n\n" + guide
            decoded["answer"] = answer
            decoded["content"] = answer
            if answer_key not in {"answer", "content"}:
                decoded[answer_key] = answer

    # Build a route graph without duplicating the homepage. Filter nodes by the
    # actual current screen; for example /aprill is a separate help page, not a
    # shortcut card inside the screenshot-confirmed profile/CURRENT PLAN panel.
    current_route_query, _removed_negative_route_clause = _effective_site_help_query(_current_user_query(machine_request))
    all_selected_area_ids = [str(area.get("id") or "") for area in areas if isinstance(area, dict)]
    # Whole-site requests get an overview canvas instead of being mistaken for a
    # profile quick-link request just because the map also contains settings.
    current_ui_targets: list[str] = []
    for _contract in _site_ui_action_contracts(machine_request):
        _navigation = _contract.get("ui_navigation") if isinstance(_contract.get("ui_navigation"), dict) else {}
        for _target in [_contract.get("target"), *(_navigation.get("targets") if isinstance(_navigation.get("targets"), list) else [])]:
            _target = _text(_target)
            if _target and _target not in current_ui_targets:
                current_ui_targets.append(_target)
    # Keep the semantic target selected by Interpretation all the way through
    # the final SVG pass. URL-only area ids are insufficient when several
    # controls live under the same route, e.g. / chat response controls.
    for _target in site_map.get("semantic_targets", []) if isinstance(site_map.get("semantic_targets"), list) else []:
        _target = _text(_target)
        if _target and _target not in current_ui_targets:
            current_ui_targets.append(_target)
    screen_id = "overview" if full_interface_overview else _site_screen_for_query(current_route_query, all_selected_area_ids, current_ui_targets)
    pointer_requested = screen_id in {"response-share-community", "graph-controls", "chat-side-panels", "free-media-referral", "community-invite", "community-friends", "community-profile", "community-post-actions"} or feedback_help or bool(re.search(r"(?:стрелк\w*|указател\w*|укаж\w*|отмет\w*|подсвет\w*|arrow|pointer|point\s+to)", current_route_query, re.IGNORECASE))
    pointer_target = (
        "share" if screen_id == "response-share-community" else
        "invite" if screen_id == "community-invite" else
        "search" if screen_id == "community-friends" else
        "nickname" if screen_id == "community-profile" else
        "post" if screen_id == "community-post-actions" else
        "graph" if screen_id == "graph-controls" else
        "history-panel" if screen_id == "chat-side-panels" and re.search(r"(?:истори\w*|history)", current_route_query, re.I) else
        "profile-panel" if screen_id == "chat-side-panels" else
        "invite" if screen_id == "free-media-referral" else
        ""
    )
    if not pointer_target and re.search(r"(?:истори\w*\s+диалог\w*|saved\s+dialogues?|\bhistory\b)", current_route_query, re.IGNORECASE):
        pointer_target = "history"
    elif re.search(r"(?:сообществ\w*|community)", current_route_query, re.IGNORECASE):
        pointer_target = "space"
    elif re.search(r"(?:поддержк\w*|contact\s+support|\bsupport\b)", current_route_query, re.IGNORECASE):
        pointer_target = "support"
    elif re.search(r"(?:настройк\w*|профил\w*|settings|profile)", current_route_query, re.IGNORECASE):
        pointer_target = "settings"
    if full_interface_overview:
        primary_overview_ids = {"chat", "attachments", "image-controls", "settings", "history", "space", "direct", "support"}
        diagram_route_rows = [row for row in route_rows if row.get("id") in primary_overview_ids]
    elif screen_id == "plans-payment":
        diagram_route_rows = [row for row in route_rows if row.get("id") in {"chat", "settings"}]
    elif screen_id == "profile":
        if pointer_requested and pointer_target:
            # A pointer request should show only the profile gateway and named
            # target; the general chat shortcut is not a second competing target.
            diagram_route_rows = [row for row in route_rows if row.get("id") in {"settings", pointer_target}]
        else:
            diagram_route_rows = [row for row in route_rows if row.get("id") in {"settings", "chat", "history", "space", "support"}]
    else:
        diagram_route_rows = list(route_rows)

    # Profile maps start at /settings, not at the chat homepage. This prevents
